/** All translations for zizhitongjian ch.032 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑第032卷", literal: "Zizhi Tongjian, Volume 32.", idiomatic: "Zizhi Tongjian, Volume 32." },
  { zh: "【漢紀二十四】起著雍涒灘，盡昭陽赤奮若，凡六年。", literal: "[Han Annals 24] From Zhuoyong Zuitan through Zhaoyang Chifenruo; six years in all.", idiomatic: "[Han Annals 24] From Zhuoyong Zuitan through Zhaoyang Chifenruo—six years in all." },
  { zh: "春，正月，上行幸甘泉，郊泰畤；", literal: "In spring, the first month, the emperor traveled in favor to Sweet Springs and sacrificed at the Great Altars;", idiomatic: "In spring, the first month, the emperor went to Sweet Springs and offered sacrifice at the Great Altars;" },
  { zh: "大赦天下，三月，行幸河東，祠后土。", literal: "a general amnesty was proclaimed; in the third month, he traveled in favor to Hedong and sacrificed to the Queen of Earth.", idiomatic: "he pardoned the empire; in the third month he traveled to Hedong and sacrificed to the Queen of Earth." },
  { zh: "夏，大旱。", literal: "In summer, a great drought.", idiomatic: "In summer, a great drought struck." },
  { zh: "四月，癸未，長樂臨華殿、未央宮東司馬門皆災。", literal: "In the fourth month, on guiwei, Linhua Hall in Everlasting Joy and the Eastern Sima Gate of Weiyang Palace all suffered fire.", idiomatic: "In the fourth month, on guiwei, Linhua Hall in Everlasting Joy and the Eastern Sima Gate of Weiyang Palace burned." },
  { zh: "六月，甲午，霸陵園門闕災。", literal: "In the sixth month, on jiawu, the gate-towers of Baling's park enclosure suffered fire.", idiomatic: "In the sixth month, on jiawu, the gate-towers of Baling's park enclosure burned." },
  { zh: "秋，七月，辛未晦，日有食之。", literal: "In autumn, the seventh month, on the last day xinwei, there was an eclipse of the sun.", idiomatic: "In autumn, the seventh month, on the last day xinwei, the sun was eclipsed." },
  { zh: "冬，十一月，庚申，衛將軍王商病免。", literal: "In winter, the eleventh month, on gengshen, General of the Guard Wang Shang was dismissed for illness.", idiomatic: "In winter, the eleventh month, on gengshen, General of the Guard Wang Shang resigned for illness." },
  { zh: "梁王立驕恣無度，至一日十一犯法。", literal: "The Prince of Liang, Li, was arrogant and unrestrained beyond measure, to the point of eleven violations of law in a single day.", idiomatic: "Prince of Liang Liu Li grew arrogant beyond all bounds—eleven violations of law in a single day." },
  { zh: "相禹奏「立對外家怨望，有惡言。", literal: "Chancellor Yu memorialized: \"Li, facing his wife's kin, harbored resentment and spoke evil words.", idiomatic: "Chancellor Yu memorialized: \"Liu Li, resentful toward his wife's family, spoke slanderously." },
  { zh: "」有司案驗，因發其與姑園子奸事，奏「立禽獸行，請誅。", literal: "\" The authorities investigated and verified, and thereby uncovered his incest with his father's sister's son's wife Yuanzi; they memorialized: \"Li's conduct is that of a beast—request execution.\"", idiomatic: "\" Investigators confirmed the charge, then uncovered his affair with his cousin Yuanzi's wife; they memorialized: \"Liu Li behaves like a beast—execute him.\"" },
  { zh: "」太中大夫谷永上書曰：「臣聞禮，天子外屏，不欲見外也。", literal: "\" Grandee of the Palace Gu Yong submitted a memorial saying: \"Your servant has heard that in ritual the Son of Heaven has an outer screen—he does not wish to be seen from outside.", idiomatic: "\" Palace Grandee Gu Yong submitted: \"I have heard that in ritual the Son of Heaven keeps an outer screen—he does not wish outsiders to look in." },
  { zh: "是故帝王之意，不窺人閨門之私，聽聞中冓之言。", literal: "Therefore the intent of emperors and kings is not to peer into the private affairs behind others' inner gates, nor to hear words of inner scandal.", idiomatic: "Therefore emperors and kings do not pry into private chambers or heed tales of household scandal." },
  { zh: "《春秋》為親者諱。", literal: "The Spring and Autumn Annals conceals faults for kin.", idiomatic: "The Spring and Autumn conceals the faults of kin." },
  { zh: "今梁王年少，頗有狂病，始以惡言按驗，既無事實，而發閨門之私，非本章所指。", literal: "Now the Prince of Liang is young and somewhat afflicted with madness; the case began with investigation of evil speech, yet there was no factual basis, while what was exposed was private scandal within the inner gates—not what this chapter's charge aimed at.", idiomatic: "The Prince of Liang is young and somewhat unbalanced; the case began with slander, yet no proof was found, while investigators exposed private scandal within the household—not the charge at hand." },
  { zh: "王辭又不服，猥強劾立，傅致難明之事，獨以偏辭成罪斷獄，無益於治道。", literal: "The prince's plea was also not accepted; they forcibly impeached Li, attached hard-to-clarify matters, and convicted and judged the case on one-sided words alone—of no benefit to the way of governance.", idiomatic: "The prince's denial went unheard; they forced the case, piled on obscure charges, and convicted him on one-sided testimony—nothing good for governance." },
  { zh: "污蔑宗室以內亂之惡，披布宣揚於天下，非所以為公族隱諱，增朝廷之榮華，昭聖德之風化也。", literal: "To slander the imperial clan with the evil of inner disorder, spread and proclaimed throughout the realm—this is not the means to conceal and excuse the ducal house, increase the court's glory, or display sage virtue's transforming influence.", idiomatic: "To brand the imperial clan with incest and broadcast it through the realm is not how one shields royal kin, adorns the court, or displays the sage king's transforming virtue." },
  { zh: "臣愚以為王少而父同產長，年齒不倫；", literal: "Your servant foolishly thinks the prince is young while his father's uterine elder brother is senior—their years and ranks are not of a kind;", idiomatic: "I think the prince is young while his father's elder uterine brother is senior—their ages do not match;" },
  { zh: "梁國之富足以厚聘美女，招致妖麗；", literal: "the wealth of Liang state is sufficient to richly betroth beautiful women and summon bewitching charms;", idiomatic: "Liang's wealth could richly hire beauties and summon seductive women;" },
  { zh: "父同產亦有恥辱之心。", literal: "the father's uterine kin also have a sense of shame.", idiomatic: "and his father's kin still know shame." },
  { zh: "案事者乃驗問惡言，何故猥自發舒！", literal: "Those handling the case were only to verify and question the evil speech—why did they rashly expose it themselves!", idiomatic: "Investigators were charged only to examine the slander—why did they rashly expose private matters!" },
  { zh: "以三者揆之，殆非人情，疑有所迫切，過誤失言，文吏躡尋，不得轉移。", literal: "Weighing these three points, it is scarcely human feeling; I suspect he was pressed hard, misspoke in error, and clerks tracked step by step without allowing shift.", idiomatic: "Weighing all three, this scarcely fits human nature; I suspect pressure drove him to a slip of the tongue, and clerks gave him no room to retreat." },
  { zh: "萌牙之時，加恩勿治，上也。", literal: "At the sprouting stage, to add grace and not punish—that is the highest course.", idiomatic: "At the first sprouting of trouble, to show grace and forbear—that is best." },
  { zh: "既已案驗舉憲，宜及王辭不服，詔廷尉選上德通理之吏更審考清問，著不然之效，定失誤之法，而反命於下吏，以廣公族附疏之德，為宗室刷污亂之恥，甚得治親之誼。", literal: "Since investigation and impeachment under law have already been raised, it is fitting that when the prince's plea is not accepted, an edict should order the Commandant of Justice to select officers of highest virtue who penetrate principle to re-examine with clear questioning, establish proof of innocence, fix the law of error, and return the mandate to the lower officials—to broaden the virtue of drawing near yet keeping distant among the ducal house, wash away the shame of filth and disorder for the imperial clan, and greatly obtain the propriety of governing kin.", idiomatic: "Since the case has already been raised, when the prince still denies guilt the emperor should order the Commandant of Justice to choose officers of highest virtue and clearest judgment to re-examine, prove innocence if it exists, fix the law of error, and return the matter to the lower officials—to extend mercy toward distant kin, cleanse the clan's shame, and honor the propriety of governing one's own house." },
  { zh: "」天子由是寢而不治。", literal: "\" Thereupon the Son of Heaven shelved the matter and did not pursue it.", idiomatic: "\" The emperor thereupon shelved the case and pursued it no further." },
  { zh: "是歲，司隸校尉蜀郡何武為京兆尹。", literal: "This year, Metropolitan Commandant He Wu of Shu commandery became Metropolitan of Jingzhao.", idiomatic: "This year, Metropolitan Commandant He Wu of Shu was appointed Metropolitan of Jingzhao." },
  { zh: "武為吏，守法盡公，進善退惡，其所居無赫赫名，去後常見思。", literal: "As an official, Wu upheld the law to the utmost in fairness, advanced the good and removed the wicked; where he served there was no resounding fame, yet after he left he was often remembered.", idiomatic: "As an official Wu upheld the law with utter fairness, promoted the worthy and removed the wicked; where he served he won no loud fame, yet after he left men often remembered him." },
  { zh: "春，正月，己亥朔，日有食之。", literal: "In spring, the first month, on the first day jihai, there was an eclipse of the sun.", idiomatic: "In spring, the first month, on the first day jihai, the sun was eclipsed." },
  { zh: "壬戌，王商復為大司馬、衛將軍。", literal: "On renxu, Wang Shang was again made Grand Marshal and General of the Guard.", idiomatic: "On renxu, Wang Shang was restored as Grand Marshal and General of the Guard." },
  { zh: "三月，上行幸雍，祠五畤。", literal: "In the third month, the emperor traveled in favor to Yong and sacrificed at the Five Altars.", idiomatic: "In the third month, the emperor went to Yong and sacrificed at the Five Altars." },
  { zh: "夏，四月，丁酉，無雲而雷，有流星從日下東南行，四面燿燿如雨，自晡及昏而止。", literal: "In summer, the fourth month, on dingyou, without clouds there was thunder; a meteor went from below the sun southeastward, on all sides glittering like rain, from the hour of shen until dusk and then stopping.", idiomatic: "In summer, the fourth month, on dingyou, thunder rolled under a cloudless sky; a meteor streaked from beneath the sun toward the southeast, glittering on every side like rain from mid-afternoon until dusk." },
  { zh: "赦天下。", literal: "The empire was pardoned.", idiomatic: "The empire was pardoned." },
  { zh: "秋，七月，有星孛於東井。", literal: "In autumn, the seventh month, a broom star appeared in the Well mansion.", idiomatic: "In autumn, the seventh month, a comet appeared in the Well mansion." },
  { zh: "上以災變，博謀群臣。", literal: "Because of disaster and anomaly, the emperor broadly sought counsel from his ministers.", idiomatic: "Alarmed by omens, the emperor sought broad counsel from his ministers." },
  { zh: "北地太守谷永對曰：「王者躬行道德，承順天地，則五征時序，百姓壽考，符瑞並降；", literal: "Anding Administrator Gu Yong replied: \"When a king personally practices virtue and complies with Heaven and Earth, then the five portents come in season, the hundred surnames live long, and talismans and auspices descend together;", idiomatic: "Anding Administrator Gu Yong replied: \"When a king personally practices virtue and aligns with Heaven and Earth, the five portents fall in season, the people live long lives, and auspicious signs descend together;" },
  { zh: "失道妄行，逆天暴物，則咎徵著郵，妖孽並見，饑饉荐臻；", literal: "when he loses the Way and acts rashly, defies Heaven and ravages things, then blame-signs appear like mail, demons and monsters appear together, and famine comes again and again;", idiomatic: "when he loses the Way, acts rashly, defies Heaven and ravages creation, blame-signs arrive like post, demons and monsters appear together, and famine returns again and again;" },
  { zh: "終不改寤，惡洽變備，不復譴告，更命有德。", literal: "if to the end he does not reform and awaken, evil saturates and change is complete, and there is no further reproof and warning—Heaven appoints another of virtue.", idiomatic: "if he never awakens, evil saturates and change is complete, and Heaven sends no further warning—it appoints another of virtue." },
  { zh: "此天地之常經，百王之所同也。", literal: "This is Heaven and Earth's constant canon, what the hundred kings share alike.", idiomatic: "This is Heaven and Earth's constant law, shared by the hundred kings." },
  { zh: "加以功德有厚薄，期質有修短，時世有中季，天道有盛衰。", literal: "Add to this that merit and virtue have thick and thin, allotted span has long and short, the age has its middle and declining seasons, and Heaven's Way has flourishing and decline.", idiomatic: "Moreover merit may be thick or thin, allotted years long or short, ages have their middle and declining seasons, and Heaven's Way has its rise and fall." },
  { zh: "陛下承八世之功業，當陽數之標季，涉三七之節紀，遭《無妄》之卦運，直百六之災厄，三難異科，雜焉同會。", literal: "Your Majesty inherits the achievement of eight generations, stands at the yang number's marked declining season, passes the three-seven cycle's junctures, meets the hexagram Wuwang's turning fortune, faces straight on the hundred-six calamities, and three hardships of different kinds meet mixed together.", idiomatic: "Your Majesty inherits eight generations of achievement, stands at the yang cycle's declining mark, passes the three-seven juncture, meets the hexagram Wuwang's turning fortune, faces the hundred-six calamities, and three hardships of different kinds converge at once." },
  { zh: "建始元年以來，二十載間，群災大異，交錯鋒起，多於《春秋》所書。", literal: "Since the first year of Jianshi, across twenty years, mass disasters and great anomalies have crossed and surged like blades, more than the Spring and Autumn records.", idiomatic: "Since the first year of Jianshi, across twenty years, mass disasters and great omens have crossed and surged, outnumbering what the Spring and Autumn records." },
  { zh: "內則為深宮後庭，將有驕臣悍妾、醉酒狂悖卒起之敗，北宮苑囿街巷之中、臣妾之家幽閒之處征舒、崔杼之亂；", literal: "Within, it will be the deep palace and rear court—there will be the defeat of arrogant ministers and fierce consorts, drunken madness and violent defiance suddenly arising; in Northern Palace gardens, lanes, and alleys, in secluded places of ministers' and concubines' houses—the disorders of Zheng Shu and Cui Zhu;", idiomatic: "Within lie the deep palace and rear courts—arrogant ministers, fierce consorts, drunken madness and sudden ruin; in Northern Palace gardens, lanes, and alleys, in secluded chambers of ministers' households—the disorders of Zheng Shu and Cui Zhu;" },
  { zh: "外則為諸夏下土，將有樊並、蘇令、陳勝、項梁奮臂之禍。", literal: "Without, it will be the myriad Xia and the lower lands—there will be the calamities of Fan Bing, Su Ling, Chen Sheng, and Xiang Liang raising their arms.", idiomatic: "Without lie the myriad Xia and the lower realm—the calamities of Fan Bing, Su Ling, Chen Sheng, and Xiang Liang raising their arms." },
  { zh: "安危之分界，宗廟之至憂，臣永所以破膽寒心，豫言之累年。", literal: "The boundary between safety and peril, the utmost worry of the ancestral temples—this is why your servant Yong has shattered his gall and chilled his heart, speaking of it beforehand for many years.", idiomatic: "The boundary between safety and ruin, the ancestral temples' gravest fear—this is why I have shattered my courage and chilled my heart, warning of it for years." },
  { zh: "下有其萌，然後變見於上，可不致慎！", literal: "Below there is its sprouting, and only then change appears above—how can one not be utterly cautious!", idiomatic: "Below the sprout appears first; only then does the omen show above—how can one not be utterly cautious!" },
  { zh: "禍起細微，奸生所易。", literal: "Calamity rises from the minute; treachery is born from what is easy.", idiomatic: "Calamity rises from the minute; treachery is born from what seems easy." },
  { zh: "願陛下正君臣之義，無復與群小□葉黷燕飲；", literal: "I wish Your Majesty would rectify the righteousness between ruler and minister, and no longer with petty men □ ye du in debauched feasting and drinking;", idiomatic: "I beg Your Majesty to set right the bond between ruler and minister, and no longer debauch with petty men □ ye du in secret revels;" },
  { zh: "勤三綱之嚴，修後宮之政，抑遠驕妒之寵，崇近婉順之行；", literal: "strengthen the sternness of the three bonds, repair governance of the rear palace, suppress and keep distant the favor of arrogant jealousy, and exalt and draw near conduct that is gentle and compliant;", idiomatic: "strengthen the three bonds, repair the rear palace's governance, keep distant the arrogant and jealous favorites, and honor those gentle and compliant in conduct;" },
  { zh: "朝覲法駕而後出，陳兵清道而後行，無復輕身獨出，飲食臣妾之家。", literal: "attend court with the law carriage before going out, array troops to clear the road before traveling, and no longer go forth lightly in person alone or dine in ministers' and concubines' houses.", idiomatic: "attend court with the imperial carriage before going abroad, clear the road with troops before traveling, and never again go abroad lightly alone or dine in ministers' households." },
  { zh: "三者既除，內亂之路塞矣。", literal: "Once these three are removed, the road to inner disorder is blocked.", idiomatic: "Remove these three and the road to inner disorder is blocked." },
  { zh: "諸夏舉兵，萌在民饑饉而吏不恤，興於百姓困而賦斂重，發於下怨離而上不知。", literal: "When the myriad Xia raise arms, it sprouts from the people starving while officials do not pity; it rises when the hundred surnames are trapped while levies are heavy; it breaks out when those below resent and part while those above do not know.", idiomatic: "When the myriad Xia take up arms, it begins with famine while officials show no pity; it rises when the people are trapped under heavy levies; it erupts when those below resent and part while those above know nothing." },
  { zh: "《傳》曰：『饑而不損，茲謂泰，厥咎亡。", literal: "The Commentary says: 'In famine yet not reducing—this is called excess; its blame is extinction.", idiomatic: "The Commentary says: 'In famine yet not reducing—this is excess; its blame is extinction." },
  { zh: "』比年郡國傷於水災，禾麥不收，宜損常稅之時，而有司奏請加賦，甚繆經義，逆於民心，市怨趨禍之道也。", literal: "' In recent years commanderies and states have been harmed by flood disaster, grain and wheat not harvested—it is the time when regular taxes ought to be reduced, yet the authorities memorialized requesting increased levies—greatly perverse to canonical meaning, contrary to the people's hearts, the way of courting resentment and rushing toward calamity.", idiomatic: "' In recent years commanderies and states have suffered floods, grain and wheat failed—it is time to cut regular taxes, yet officials memorialized to increase levies—deeply perverse to canonical meaning, contrary to the people's hearts, the way of courting resentment and rushing toward disaster." },
  { zh: "臣願陛下勿許加賦之奏，益減奢泰之費，流恩廣施，振贍困乏，敕勸耕桑，以慰綏元元之心，諸夏之亂庶幾可息。", literal: "Your servant wishes Your Majesty not to approve memorials to increase levies, further reduce extravagant excess in expenditure, spread favor broadly, relieve and support the exhausted, command and encourage plowing and sericulture, to comfort and pacify the hearts of the common people—then disorder among the myriad Xia may perhaps cease.", idiomatic: "I beg Your Majesty to reject memorials for increased levies, cut extravagant spending further, spread favor broadly, relieve the exhausted, command plowing and sericulture, comfort the common people's hearts—and disorder among the myriad Xia may perhaps cease." },
  { zh: "中壘校尉劉向上書曰：「臣聞帝舜戒伯禹『毋若丹朱敖』，周公戒成王『毋若殷王紂』，聖帝明王常以敗亂自戒，不諱廢興，故臣敢極陳其愚，唯陛下留神察焉！", literal: "Central Ramparts Commandant Liu Xiang submitted a memorial saying: \"Your servant has heard that Emperor Shun warned Bo Yu, 'Be not like Dan Zhu's arrogance,' and the Duke of Zhou warned King Cheng, 'Be not like King Zhou of Yin'—sage emperors and enlightened kings constantly take ruin and disorder as their warning, and do not avoid speaking of decline and rise; therefore your servant dares to state his folly to the limit—only may Your Majesty keep your spirit and examine it!", idiomatic: "Central Ramparts Commandant Liu Xiang submitted: \"I have heard that Emperor Shun warned Bo Yu, 'Be not like Dan Zhu's arrogance,' and the Duke of Zhou warned King Cheng, 'Be not like King Zhou of Yin'—sage emperors and enlightened kings take ruin as their warning and do not shrink from speaking of rise and fall; therefore I dare state my folly to the limit—may Your Majesty examine it with care!" },
  { zh: "謹案《春秋》二百四十二年，日食三十六，今連三年比食，自建始以來，二十歲間而八食，率二歲六月而一發，古今罕有。", literal: "I respectfully note that in the Spring and Autumn's two hundred forty-two years there were thirty-six solar eclipses; now for three years in succession there have been successive eclipses; since Jianshi began, in twenty years there have been eight eclipses—on average one every two years and six months—a thing rare in past and present.", idiomatic: "I note that in the Spring and Autumn's two hundred forty-two years there were thirty-six solar eclipses; now eclipses have come three years running; since Jianshi began, eight eclipses in twenty years—on average one every two years and six months—rare in any age." },
  { zh: "異有小大希稠，佔有舒疾緩急。", literal: "Anomalies have large and small, sparse and dense; prognostication has relaxed and urgent, slow and quick.", idiomatic: "Omens vary in size and frequency; prognostication in pace and urgency." },
  { zh: "觀秦、漢之易世，覽惠、昭之無後，察昌邑之不終，視孝宣之紹起，皆有變異著於漢紀。", literal: "Observing Qin and Han's change of age, surveying Hui and Zhao's lack of heirs, examining Changyi's failure to reach the end, viewing Emperor Xiaoxuan's succession and rise—all had anomalies recorded in Han's annals.", idiomatic: "Observe Qin and Han's change of dynasty, Hui and Zhao's lack of heirs, Changyi's failure to endure, Emperor Xuan's succession and rise—each had omens recorded in Han's annals." },
  { zh: "天之去就，豈不昭昭然哉！", literal: "Heaven's departing and approaching—how is it not brilliantly clear!", idiomatic: "Heaven's departing and approaching—how brilliantly clear!" },
  { zh: "臣幸得托末屬，誠見陛下寬明之德，冀銷大異而興高宗、成王之聲，以崇劉氏，故懇懇數奸死亡之誅！", literal: "Your servant, fortunate to attach to the farthest branch, truly sees Your Majesty's broad and bright virtue, and hopes to dispel great anomalies and raise the renown of Gaozong and King Cheng, to exalt the Liu house—therefore earnestly and repeatedly courting the punishment of death!", idiomatic: "Fortunate to stand among the farthest kin, I truly see Your Majesty's broad and bright virtue, and hope to dispel great omens and raise the renown of Gaozong and King Cheng to exalt the house of Liu—therefore I earnestly court death again and again!" },
  { zh: "天文難以相曉，臣雖圖上，猶須口說，然後可知；", literal: "Astronomy is hard to make mutually understood; though your servant submits charts, still oral explanation is needed before it can be known;", idiomatic: "Astronomy is hard to grasp from charts alone; though I submit diagrams, only speech can make them clear;" },
  { zh: "願賜清燕之閒，指圖陳狀。", literal: "I wish to be granted leisure in pure ease, to point at the charts and set forth the facts.", idiomatic: "I beg leave in a quiet hour to point at the charts and set forth the facts." },
  { zh: "」上輒入之，然終不能用也。", literal: "\" The emperor always received them, yet in the end could not employ him.", idiomatic: "\" The emperor always received them, yet in the end never acted on them." },
  { zh: "紅陽侯立舉陳鹹方正，對策，拜為光祿大夫、給事中。", literal: "Marquis of Hongyang Li recommended Chen Xian as Incorrupt and Upright; answering the policy questions, he was appointed Household Grandee and Attendant Within.", idiomatic: "Marquis of Hongyang Wang Li recommended Chen Xian as Incorrupt and Upright; after answering the policy questions, Chen was appointed Household Grandee and Attendant Within." },
  { zh: "丞相方進復奏「鹹前為九卿，坐為貪邪免，不當蒙方正舉，備內朝臣」；", literal: "Chancellor Fang Jin again memorialized: \"Xian was formerly one of the Nine Ministers, dismissed for sitting in corruption and wickedness—he ought not receive recommendation as Incorrupt and Upright; prepare him as an inner-court minister\";", idiomatic: "Chancellor Fang Jin again memorialized: \"Xian was formerly one of the Nine Ministers and was dismissed for corruption—he ought not receive recommendation as Incorrupt and Upright; keep him among the inner-court ministers\";" },
  { zh: "並劾「紅陽侯立選舉故不以實。", literal: "and jointly impeached \"Marquis of Hongyang Li's selection and recommendation was intentionally not according to fact.", idiomatic: "and jointly impeached \"Marquis of Hongyang Wang Li's recommendation was knowingly false." },
  { zh: "」有詔免鹹，勿劾立。", literal: "\" An edict dismissed Xian and did not impeach Li.", idiomatic: "\" An edict dismissed Xian and did not prosecute Wang Li." },
  { zh: "十二月，乙未，王商為大將軍。", literal: "In the twelfth month, on yiwei, Wang Shang became Grand General.", idiomatic: "In the twelfth month, on yiwei, Wang Shang was made Grand General." },
  { zh: "辛亥，商薨。", literal: "On xinhai, Shang died.", idiomatic: "On xinhai, Shang died." },
  { zh: "其弟紅陽侯立次當輔政，先是立使客因南郡太守李尚占墾草田數百頃，上書以入縣官，貴取其直一萬萬以上，丞相司直孫寶發之，上由是廢立，而用其弟光祿勳曲陽侯根。", literal: "His younger brother Marquis of Hongyang Li was next in line to assist in government; earlier Li had agents through Nan commandery Administrator Li Shang seize several hundred qing of reclaimed grassland, memorialize to turn it in to the state treasury, and demand payment at a price of more than a hundred million; Chancellor's Director of Justice Sun Bao exposed it; the emperor thereby dismissed Li and used his younger brother Household Grandee Marquis of Qunyang Gen.", idiomatic: "His younger brother Marquis of Hongyang Wang Li stood next in line to govern; earlier Wang Li had agents through Nan commandery Administrator Li Shang seize several hundred qing of reclaimed grassland, memorialize to surrender it to the state, and demand more than a hundred million in payment; Chancellor's Director of Justice Sun Bao exposed the scheme; the emperor dismissed Wang Li and turned to his younger brother, Household Grandee Marquis of Qunyang Wang Gen." },
  { zh: "庚申，以根為大司馬、驃騎將軍。", literal: "On gengshen, Gen was made Grand Marshal and Rapid Cavalry General.", idiomatic: "On gengshen, Wang Gen was appointed Grand Marshal and Rapid Cavalry General." },
  { zh: "特進、安昌侯張禹請平陵肥牛亭地；", literal: "Extraordinary Advancement, Marquis of Anchang Zhang Yu requested the land of Pingling's Fat Ox Pavilion;", idiomatic: "Extraordinary Advancement, Marquis of Anchang Zhang Yu requested the land of Pingling's Fat Ox Pavilion;" },
  { zh: "曲陽侯根爭，以為此地當平陵寢廟，衣冠所出遊道，宜更賜禹它地。", literal: "Marquis of Qunyang Gen contested it, holding that this land faces Pingling's tomb temple—the road by which robes and caps go forth—and that other land ought to be granted Yu instead.", idiomatic: "Marquis of Qunyang Wang Gen objected, holding that the land faced Pingling's tomb temple—the road by which imperial regalia passed—and that other land ought to be granted Zhang Yu instead." },
  { zh: "上不從，卒以賜禹。", literal: "The emperor did not follow him; in the end he granted it to Yu.", idiomatic: "The emperor refused; in the end he granted it to Zhang Yu." },
  { zh: "根由是害禹寵，數毀惡之。", literal: "Gen thereby resented Yu's favor and repeatedly slandered and maligned him.", idiomatic: "Wang Gen thereupon resented Zhang Yu's favor and repeatedly slandered him." },
  { zh: "天子愈益敬厚禹，每病，輒以起居聞，車駕自臨問之。", literal: "The Son of Heaven ever more respected and honored Yu; whenever he was ill, the emperor at once sent word of his own well-being, and the imperial carriage personally visited to inquire.", idiomatic: "The emperor grew ever more respectful and generous toward Zhang Yu; whenever he fell ill, the emperor sent word of his own health and visited in person." },
  { zh: "上親拜禹床下，禹頓首謝恩。", literal: "The emperor personally bowed below Yu's couch; Yu prostrated himself in thanks for grace.", idiomatic: "The emperor bowed before Zhang Yu's couch; Yu prostrated himself in thanks." },
  { zh: "禹小子未有官，禹數視其小子，上即禹床下拜為黃門郎、給事中。", literal: "Yu had a young son without office; Yu repeatedly looked at his young son, and the emperor, right below Yu's couch, appointed him Yellow Gate Gentleman and Attendant Within.", idiomatic: "Zhang Yu's young son held no office; as Yu often gazed at the boy, the emperor, there below the couch, appointed him Yellow Gate Gentleman and Attendant Within." },
  { zh: "禹雖家居，以特進為天子師，國家每有大政，必與定議。", literal: "Though Yu dwelt at home, as Extraordinary Advancement he was the Son of Heaven's teacher; whenever the state had great policy, he was always joined in settling deliberation.", idiomatic: "Though Zhang Yu lived at home, as Extraordinary Advancement he was the emperor's teacher; whenever the state faced great policy, he was always consulted." },
  { zh: "時吏民多上書言災異之應，譏切王氏專政所致，上意頗然之，未有以明見，乃車駕至禹弟，辟左右，親問禹以天變，因用吏民所言王氏事示禹。", literal: "At the time many officials and commoners submitted memorials on how disaster and anomaly corresponded, mocking that it was caused by the Wang clan's monopoly of government; the emperor's mind largely agreed, yet had no clear way to show it; he then drove his carriage to Yu's residence, dismissed those at left and right, and personally asked Yu about Heaven's changes, and thereby showed Yu what officials and commoners had said about the Wang affair.", idiomatic: "At the time many officials and commoners submitted memorials linking omens to Wang dominance; the emperor largely agreed yet had no clear course; he drove to Zhang Yu's residence, dismissed his attendants, asked him about Heaven's changes, and showed him what the memorials said of the Wangs." },
  { zh: "禹自見年老，子孫弱，又與曲陽侯不平，恐為所怨，則謂上曰：「《春秋》日食、地震，或為諸侯相殺，夷狄侵中國。", literal: "Yu, seeing himself old, his sons and grandsons weak, and also at odds with Marquis of Qunyang, fearing to be resented by him, then said to the emperor: \"In the Spring and Autumn, solar eclipses and earthquakes were sometimes because feudal lords killed one another, or barbarians invaded the Central States.", idiomatic: "Zhang Yu, seeing himself old, his sons and grandsons weak, and at odds with Marquis of Qunyang, fearing resentment, told the emperor: \"In the Spring and Autumn, solar eclipses and earthquakes sometimes meant feudal lords killing one another or barbarians invading the Central States." },
  { zh: "災變之意，深遠難見，故聖人罕言命，不語怪神，性與天道，自子貢之屬不得聞，何況淺見鄙儒之所言。", literal: "The intent of disaster and anomaly is deep and far, hard to see; therefore sages rarely speak of fate, do not discuss strange spirits—nature and Heaven's Way, from Zi Gong's sort down, could not hear them; how much less what shallow-sighted vulgar ru say.", idiomatic: "The meaning of omens is deep and far, hard to discern; therefore sages rarely speak of fate and do not discuss strange spirits—nature and Heaven's Way were beyond even Zi Gong and his peers; how much less the shallow talk of vulgar scholars." },
  { zh: "陛下宜修政事，以善應之，與下同其福喜，此經義意也。", literal: "Your Majesty ought to repair government affairs and respond with goodness, sharing fortune and joy with those below—this is the meaning of canonical righteousness.", idiomatic: "Your Majesty ought to repair government and answer with goodness, sharing fortune and joy with the people below—this is canonical righteousness." },
  { zh: "新學小生，亂道誤人，宜無信用，以經術斷之。", literal: "New-learning young fellows disorder the Way and mislead people—they ought not be trusted; judge by classical learning.", idiomatic: "New-learning youths disorder the Way and mislead men—they ought not be trusted; judge by classical learning." },
  { zh: "」上雅信愛禹，由此不疑王氏。", literal: "\" The emperor from youth trusted and loved Yu; thereby he no longer doubted the Wang clan.", idiomatic: "\" The emperor had long trusted and loved Zhang Yu; thereby he no longer doubted the Wangs." },
  { zh: "後曲陽侯根及諸王子弟聞知禹言，皆喜說，遂親就禹。", literal: "Later Marquis of Qunyang Gen and the various Wang princes' sons and younger brothers, hearing Yu's words, were all pleased and drew near Yu in person.", idiomatic: "Later Marquis of Qunyang Wang Gen and the various Wang princes' sons and younger brothers, hearing Zhang Yu's words, were all pleased and drew near him in person." },
  { zh: "故槐裡令朱雲上書求見，公卿在前，雲曰：「今朝廷大臣，上不能匡主，下無以益民，皆尸位素餐，孔子所謂『鄙夫不可與事君，苟患失之，亡所不至』者也！", literal: "Former Huaili magistrate Zhu Yun submitted a memorial requesting audience; with the dukes and ministers before him, Yun said: \"Now the great ministers of court, above unable to correct the ruler, below unable to benefit the people—all hold office and eat salary in vain, of the sort Confucius called 'the base man cannot serve his lord; if he fears losing his position, there is nothing he will not do'!", idiomatic: "Former Huaili magistrate Zhu Yun submitted a memorial requesting audience; with the highest ministers before him, Yun said: \"Today's court ministers, above unable to correct the ruler, below unable to benefit the people—all hold office and eat salary in vain, of the sort Confucius called 'the base man cannot serve his lord; if he fears losing his post, there is nothing he will not do'!" },
  { zh: "臣願賜尚方斬馬劍，斷佞臣一人頭以厲其餘！", literal: "Your servant wishes to be granted the Palace Provisioner's horse-slaying sword, to cut off one flatterer's head and warn the rest!", idiomatic: "I beg the Palace Provisioner's horse-slaying sword, to cut off one flatterer's head and warn the rest!" },
  { zh: "」上問：「誰也？", literal: "\" The emperor asked: \"Who?\"", idiomatic: "\" The emperor asked: \"Who?\"" },
  { zh: "」對曰：「安昌侯張禹！", literal: "\" He replied: \"Marquis of Anchang Zhang Yu!\"", idiomatic: "\" He replied: \"Marquis of Anchang Zhang Yu!\"" },
  { zh: "」上大怒曰：「小臣居下訕上，廷辱師傅，罪死不赦！", literal: "\" The emperor was greatly angry and said: \"A petty official below slanders his superior, insults his teacher in court—crime deserving death without pardon!\"", idiomatic: "\" The emperor flew into a rage: \"A petty official below slanders his superior and insults his teacher in open court—death without pardon!\"" },
  { zh: "」御史將雲下，雲攀殿檻，檻折。", literal: "\" The censor was about to take Yun down; Yun clung to the hall's balustrade and the balustrade broke.", idiomatic: "\" The censor was about to drag Yun away; Yun seized the hall balustrade and it broke." },
  { zh: "雲呼曰：「臣得下從龍逄、比干游於地下，足矣！", literal: "Yun cried: \"Your servant can go below and roam underground with Long Feng and Bi Gan—that is enough!", idiomatic: "Yun cried: \"I may roam underground with Long Feng and Bi Gan—that is enough!" },
  { zh: "未知聖朝何如耳！", literal: "I do not know what the sage court will be like!", idiomatic: "I do not know what this sage court will prove to be!" },
  { zh: "」御史遂將雲去。", literal: "\" The censor then took Yun away.", idiomatic: "\" The censor then led Yun away." },
  { zh: "於是左將軍辛慶忌免冠，解印綬，叩頭殿下曰：「此臣素著狂直於世，使其言是，一可誅；", literal: "Thereupon Left General Xin Qingji removed his cap, untied his seal cord, and prostrated himself below the hall steps saying: \"This minister has always been known in the world for mad uprightness; if his words are right, he may be executed once;", idiomatic: "Thereupon Left General Xin Qingji removed his cap, untied his seal cord, and prostrated himself below the hall steps: \"This minister has always been known for mad uprightness; if his words are right, execute him once;" },
  { zh: "其言非，因當容之。", literal: "if his words are wrong, he ought therefore to be tolerated.", idiomatic: "if his words are wrong, he ought to be tolerated." },
  { zh: "臣敢以死爭！", literal: "Your servant dares dispute it unto death!", idiomatic: "I dare dispute it unto death!" },
  { zh: "」慶忌叩頭流血，上意解，然後得已。", literal: "\" Qingji prostrated himself until blood flowed; the emperor's mind eased, and only then was it stopped.", idiomatic: "\" Qingji prostrated himself until blood flowed; the emperor relented, and only then was the matter dropped." },
  { zh: "及後當治檻，上曰：「勿易，因而輯之，以旌直臣！", literal: "When later they were to repair the railing, the emperor said: \"Do not replace it; rather patch it together, to honor the upright minister!", idiomatic: "When later they were to repair the railing, the emperor said, \"Do not replace it; rather patch it together, to honor the upright minister!" },
  { zh: "匈奴搜諧單于將入朝；", literal: "The Xiongnu Chanyu Souxie was about to enter court;", idiomatic: "The Xiongnu Chanyu Souxie was about to enter court;" },
  { zh: "未入塞，病死。", literal: "before entering the frontier passes, he died of illness.", idiomatic: "before entering the frontier passes, he died of illness." },
  { zh: "弟且莫車立，為車牙若鞮單于；", literal: "His younger brother Chemoche succeeded as Chanyu Cheya Ruodi;", idiomatic: "His younger brother Chemoche succeeded as Chanyu Cheya Ruodi;" },
  { zh: "以囊知牙斯為左賢王。", literal: "Nangzhiyasi was made Left Wise King.", idiomatic: "Nangzhiyasi was made Left Wise King." },
  { zh: "北地都尉張放到官數月，復征入侍中。", literal: "Commandant of Beidi Zhang Fang, after several months in office, was again summoned in as Attendant Within.", idiomatic: "Commandant of Beidi Zhang Fang, after several months in office, was again summoned to serve as Attendant Within." },
  { zh: "太后與上書曰：「前所道尚未效，富平侯反覆來，其能默虖！", literal: "The Empress Dowager sent a letter to the emperor, saying: \"What was spoken of before has not yet taken effect; the Marquis of Fuping comes back and forth—can he be silent!", idiomatic: "The Empress Dowager sent a letter to the emperor, saying, \"What was spoken of before has not yet taken effect; the Marquis of Fuping keeps coming back—can he stay silent!" },
  { zh: "」上謝曰：「請今奉詔！", literal: "\" The emperor apologized, saying: \"I beg to obey the edict from now!", idiomatic: "\" The emperor apologized, saying, \"I beg to obey the edict from now!" },
  { zh: "」上於是出放為天水屬國都尉。", literal: "\" The emperor thereupon sent Fang out as Commandant of the Tianshui Dependent State.", idiomatic: "\" The emperor thereupon sent Fang out as Commandant of the Tianshui Dependent State." },
  { zh: "引少府許商、光祿勳師丹為光祿大夫，班伯為水衡都尉，並侍中，皆秩中二千石，每朝東宮，常從；", literal: "He brought in Minister Steward Xu Shang and Director of the Secretariat Shi Dan as Household Grandees, and Ban Bo as Chief Steward for Parks, all as Attendants Within, each at the rank of 2,000 bushels middle grade; at every audience at the Eastern Palace they regularly followed;", idiomatic: "He brought in Minister Steward Xu Shang and Director of the Secretariat Shi Dan as Household Grandees, and Ban Bo as Chief Steward for Parks, all as Attendants Within, each at the rank of 2,000 bushels middle grade; at every audience at the Eastern Palace they regularly followed;" },
  { zh: "及大政，俱使諭指於公卿。", literal: "on great affairs, all were sent to convey the intent to the excellencies and ministers.", idiomatic: "on great affairs, all were sent to convey the intent to the excellencies and ministers." },
  { zh: "上亦稍厭游宴，復修經書之業；", literal: "The emperor also gradually wearied of roaming feasts and again took up the study of the Classics;", idiomatic: "The emperor also gradually wearied of roaming and feasting and again took up the study of the Classics;" },
  { zh: "太后甚悅。", literal: "the Empress Dowager was greatly pleased.", idiomatic: "the Empress Dowager was greatly pleased." },
  { zh: "是歲，左將軍辛慶忌卒。", literal: "This year, Left General Xin Qingji died.", idiomatic: "This year, Left General Xin Qingji died." },
  { zh: "慶忌為國虎臣，遭世承平，匈奴、西域親附，敬其威信。", literal: "Qingji was a tiger minister of the state; encountering an age of lasting peace, the Xiongnu and Western Regions drew close and submitted, respecting his authority and prestige.", idiomatic: "Qingji was a tiger minister of the state; in an age of lasting peace, the Xiongnu and Western Regions drew close and submitted, respecting his authority and prestige." },
  { zh: "春，正月，上行幸甘泉，郊泰畤。", literal: "In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar.", idiomatic: "In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "三月，行幸河東，祠后土。", literal: "In the third month, he traveled to Hedong and sacrificed to the Earth Queen.", idiomatic: "In the third month, he traveled to Hedong and sacrificed to the Earth Queen." },
  { zh: "既祭，行遊龍門，登歷觀，陟西嶽而歸。", literal: "After the sacrifice, he traveled to Long Gate, ascended Liguan, climbed the Western Marchmount, and returned.", idiomatic: "After the sacrifice, he traveled to Long Gate, ascended Liguan, climbed the Western Marchmount, and returned." },
  { zh: "夏，四月，立廣陵孝王子守為王。", literal: "In summer, the fourth month, the son of King Xiao of Guangling, Shou, was established as king.", idiomatic: "In summer, the fourth month, Shou, son of King Xiao of Guangling, was established as king." },
  { zh: "初，烏孫小昆彌安日為降民所殺，諸翎侯大亂。", literal: "Earlier, the Lesser Kunmi of Wusun, Anri, was killed by surrendered people, and the various commandery-lords fell into great disorder.", idiomatic: "Earlier, the Lesser Kunmi of Wusun, Anri, was killed by surrendered people, and the various commandery-lords fell into great disorder." },
  { zh: "詔征故金城太守段會宗為左曹、中郎將、光祿大夫，使安輯烏孫；", literal: "An edict summoned the former Administrator of Jincheng Duan Huizong as Left Cao, Gentleman of the Palace, and Household Grandee, to settle and pacify Wusun;", idiomatic: "An edict summoned former Administrator of Jincheng Duan Huizong as Left Cao, Gentleman of the Palace, and Household Grandee, to settle and pacify Wusun;" },
  { zh: "立安日弟末振將為小昆彌，定其國而還。", literal: "he established Anri's younger brother Mozhenjiang as Lesser Kunmi, settled the state, and returned.", idiomatic: "he established Anri's younger brother Mozhenjiang as Lesser Kunmi, settled the state, and returned." },
  { zh: "時大昆彌雌栗靡勇健，末振將恐為所並，使貴人烏日領詐降，刺殺雌栗靡。", literal: "At the time the Greater Kunmi Xiliwei was brave and strong; Mozhenjiang feared being absorbed by him and sent a noble, Wuriling, to feign surrender and assassinate Xiliwei.", idiomatic: "At the time the Greater Kunmi Xiliwei was brave and strong; Mozhenjiang feared being absorbed by him and sent a noble, Wuriling, to feign surrender and assassinate Xiliwei." },
  { zh: "漢欲以兵討之而未能，遣中郎將段會宗立公主孫伊秩靡為大昆彌。", literal: "Han wished to punish him with troops but could not; it sent Gentleman of the Palace Duan Huizong to establish the princess's grandson Yizhimi as Greater Kunmi.", idiomatic: "Han wished to punish him with troops but could not; it sent Gentleman of the Palace Duan Huizong to establish the princess's grandson Yizhimi as Greater Kunmi." },
  { zh: "久之，大昆彌、翕侯難棲殺末振將，安日子安犁靡代為小昆彌。", literal: "After a long time, the Greater Kunmi and Xihou Nanqi killed Mozhenjiang; Anri's son Anlimi replaced him as Lesser Kunmi.", idiomatic: "After a long time, the Greater Kunmi and Xihou Nanqi killed Mozhenjiang; Anri's son Anlimi replaced him as Lesser Kunmi." },
  { zh: "漢恨不自誅末振將，復遣段會宗發戊己校尉諸國兵，即誅末振將太子番丘。", literal: "Han resented that it had not itself executed Mozhenjiang and again sent Duan Huizong to mobilize the troops of the Chief Commandant of the Western Regions and the various states to execute Mozhenjiang's heir Fanqiu on the spot.", idiomatic: "Han resented that it had not itself executed Mozhenjiang and again sent Duan Huizong to mobilize the troops of the Chief Commandant of the Western Regions and the various states to execute Mozhenjiang's heir Fanqiu on the spot." },
  { zh: "會宗恐大兵入烏孫，驚番丘，亡逃不可得，即留所發兵墊婁地，選精兵三十弩，逕至昆彌所在，召番丘，責以末振將之罪，即手劍擊殺番丘，官屬以下驚恐，馳歸。", literal: "Huizong feared that if great troops entered Wusun they would startle Fanqiu and he would flee and escape—this could not be obtained—so he left the troops he had mobilized at Dianlou, selected thirty picked crossbowmen, went straight to where the Kunmi was, summoned Fanqiu, charged him with Mozhenjiang's crime, and with his own hand struck and killed Fanqiu with a sword; officials and subordinates below were startled and afraid and galloped back.", idiomatic: "Huizong feared that if a large force entered Wusun it would startle Fanqiu into flight and he would escape—so he left the troops he had mobilized at Dianlou, selected thirty picked crossbowmen, went straight to where the Kunmi was, summoned Fanqiu, charged him with Mozhenjiang's crime, and with his own hand struck and killed Fanqiu with a sword; officials and subordinates below were startled and afraid and galloped back." },
  { zh: "小昆彌安犁靡勒兵數千騎圍會宗，會宗為言來誅之意，「今圍守殺我，如取漢牛一毛耳。", literal: "The Lesser Kunmi Anlimi mustered several thousand horsemen and besieged Huizong; Huizong explained the intent of his coming to execute, saying: \"Now if you besiege and hold and kill me, it is like plucking one hair from a Han ox.", idiomatic: "The Lesser Kunmi Anlimi mustered several thousand horsemen and besieged Huizong; Huizong explained the intent of his coming to execute, saying, \"Now if you besiege and hold and kill me, it is like plucking one hair from a Han ox." },
  { zh: "宛王、郅支頭縣槁街，烏孫所知也。", literal: "The King of Wan and Zhizhi's head hung at Gao Street—Wusun knows this.", idiomatic: "The King of Wan and Zhizhi's head hung at Gao Street—Wusun knows this." },
  { zh: "」昆彌以下服，曰：「末振將負漢，誅其子可也，獨不可告我，令飲食之邪？", literal: "\" Those from the Kunmi down submitted, saying: \"Mozhenjiang betrayed Han—executing his son is permissible; only why could you not tell me and let me give him food and drink?", idiomatic: "\" Those from the Kunmi down submitted, saying, \"Mozhenjiang betrayed Han—executing his son is permissible; only why could you not tell me and let me give him food and drink?" },
  { zh: "」會宗曰：「豫告昆彌，逃匿之，為大罪，即飲食以付我，傷骨肉恩。", literal: "\" Huizong said: \"If I told the Kunmi beforehand, he would hide him—this would be a great crime; if I let you feed and drink and then hand him to me, it would wound flesh-and-bone affection.", idiomatic: "\" Huizong said, \"If I told the Kunmi beforehand, he would hide him—this would be a great crime; if I let you feed and drink and then hand him to me, it would wound flesh-and-bone affection." },
  { zh: "故不先告。", literal: "Therefore I did not tell beforehand.", idiomatic: "Therefore I did not tell beforehand." },
  { zh: "」昆彌以下號泣罷去。", literal: "\" Those from the Kunmi down wept and wailed and then departed.", idiomatic: "\" Those from the Kunmi down wept and wailed and then departed." },
  { zh: "會宗還，奏事，天子賜會宗爵關內侯、黃金百斤。", literal: "Huizong returned and reported the affair; the Son of Heaven bestowed on Huizong the rank Marquis within the Passes and a hundred jin of gold.", idiomatic: "Huizong returned and reported the affair; the Son of Heaven bestowed on Huizong the rank Marquis within the Passes and a hundred jin of gold." },
  { zh: "會宗以難棲殺末振將，奏以為堅守都尉。", literal: "Huizong, because Nanqi had killed Mozhenjiang, memorialized to make him Commandant of Firm Defense.", idiomatic: "Huizong, because Nanqi had killed Mozhenjiang, memorialized to make him Commandant of Firm Defense." },
  { zh: "責大祿、大監以雌栗靡見殺狀，奪金印、紫綬，更與銅、墨雲。", literal: "He charged Dalu and Dajian with the circumstances of Xiliwei's being killed, stripped their gold seals and purple cords, and replaced them with bronze and ink-cloud.", idiomatic: "He charged Dalu and Dajian with the circumstances of Xiliwei's being killed, stripped their gold seals and purple cords, and replaced them with bronze and ink-cloud." },
  { zh: "末振將弟卑爰疐本共謀殺大昆彌，將眾八萬餘口北附康居，謀欲借兵兼併兩昆彌；", literal: "Mozhenjiang's younger brother Beiaizhi had originally plotted together to kill the Greater Kunmi; he led a multitude of more than eighty thousand mouths north to attach to Kangju, plotting to borrow troops and annex both Kunmis;", idiomatic: "Mozhenjiang's younger brother Beiaizhi had originally plotted together to kill the Greater Kunmi; he led a multitude of more than eighty thousand mouths north to attach to Kangju, plotting to borrow troops and annex both Kunmis;" },
  { zh: "漢復遣會宗與都護孫建並力以備之。", literal: "Han again sent Huizong and Protector Sun Jian to combine strength and guard against him.", idiomatic: "Han again sent Huizong and Protector Sun Jian to combine strength and guard against him." },
  { zh: "自烏孫分立兩昆彌，漢用憂勞，且無寧歲。", literal: "From the time Wusun was divided and two Kunmis were established, Han had worry and toil, and there were no peaceful years.", idiomatic: "From the time Wusun was divided and two Kunmis were established, Han had worry and toil, and there were no peaceful years." },
  { zh: "時康居復遣子侍漢，貢獻，都護郭舜上言；", literal: "At the time Kangju again sent a son to attend at Han and offer tribute; Protector Guo Shun submitted a memorial;", idiomatic: "At the time Kangju again sent a son to attend at Han and offer tribute; Protector Guo Shun submitted a memorial;" },
  { zh: "「本匈奴盛時，非以兼有烏孫、康居故也；", literal: "\" Originally when the Xiongnu were strong, it was not because they possessed both Wusun and Kangju;", idiomatic: "\" Originally when the Xiongnu were strong, it was not because they possessed both Wusun and Kangju;" },
  { zh: "及其稱臣妾，非以失二國也。", literal: "when they called themselves subject and concubine, it was not because they lost the two states.", idiomatic: "when they called themselves subject and concubine, it was not because they lost the two states." },
  { zh: "漢雖皆受其質子，然三國內相輸遺，交通如故；", literal: "Though Han all received their hostage sons, yet the three states within mutually sent gifts and their intercourse was as before;", idiomatic: "Though Han all received their hostage sons, yet the three states within mutually sent gifts and their intercourse was as before;" },
  { zh: "亦相候司，見便則發。", literal: "they also watched one another; when they saw an opening they struck.", idiomatic: "they also watched one another; when they saw an opening they struck." },
  { zh: "合不能相親信，離不能相臣役。", literal: "United they could not trust one another; divided they could not serve one another as subjects.", idiomatic: "United they could not trust one another; divided they could not serve one another as subjects." },
  { zh: "以今言之，結配烏孫，竟未有益，反為中國生事。", literal: "Speaking of the present, allying with Wusun in the end has not been beneficial and instead has created trouble for the Middle Kingdom.", idiomatic: "Speaking of the present, allying with Wusun in the end has not been beneficial and instead has created trouble for the Middle Kingdom." },
  { zh: "然烏孫既結在前，今與匈奴俱稱臣，義不可距。", literal: "Yet since Wusun was already allied earlier and now together with the Xiongnu all call themselves subjects, by right they cannot be rejected.", idiomatic: "Yet since Wusun was already allied earlier and now together with the Xiongnu all call themselves subjects, by right they cannot be rejected." },
  { zh: "而康居驕黠，訖不肯拜使者；", literal: "But Kangju is arrogant and crafty and to the end will not bow to envoys;", idiomatic: "But Kangju is arrogant and crafty and to the end will not bow to envoys;" },
  { zh: "都護吏至其國，坐之烏孫諸使下，王及貴人先飲食已，乃飲啖都護吏，故為無所省以誇旁國。", literal: "when the Protector's clerk reaches their state, he is seated below the various Wusun envoys; the king and nobles eat and drink first, and only afterward eat and drink with the Protector's clerk—deliberately showing no regard to boast to neighboring states.", idiomatic: "when the Protector's clerk reaches their state, he is seated below the various Wusun envoys; the king and nobles eat and drink first, and only afterward eat and drink with the Protector's clerk—deliberately showing no regard to boast to neighboring states." },
  { zh: "以此度之，何故遣子入侍？", literal: "Judging by this, why send a son to attend at court?", idiomatic: "Judging by this, why send a son to attend at court?" },
  { zh: "其欲賈市，為好辭之詐也。", literal: "Their wish is to trade in markets—it is flattery in fine words and deceit.", idiomatic: "Their wish is to trade in markets—it is flattery in fine words and deceit." },
  { zh: "匈奴，百蠻大國，今事漢甚備；", literal: "The Xiongnu are a great state among the hundred barbarians; now they serve Han very fully;", idiomatic: "The Xiongnu are a great state among the hundred barbarians; now they serve Han very fully;" },
  { zh: "聞康居不拜，且使單于有悔自卑之意。", literal: "hearing that Kangju does not bow will moreover make the Chanyu have thoughts of regret and self-abasement.", idiomatic: "hearing that Kangju does not bow will moreover make the Chanyu have thoughts of regret and self-abasement." },
  { zh: "宜歸其侍子，絕勿復使，以章漢家不通無禮之國！", literal: "You should return their attending son, cut off and never again send envoys, to make manifest that the House of Han does not communicate with states without ritual!", idiomatic: "You should return their attending son, cut off and never again send envoys, to make manifest that the House of Han does not communicate with states without ritual!" },
  { zh: "」漢為其新通，重致遠人，終羈縻不絕。", literal: "\" Han, because they had newly communicated, valued winning distant people and to the end kept them on tether without breaking off.", idiomatic: "\" Han, because they had newly communicated, valued winning distant people and to the end kept them on tether without breaking off." },
  { zh: "春，正月，丙寅，蜀郡岷山崩，壅江三日，江水竭。", literal: "In spring, the first month, on bingyin, Mount Min in Shu Commandery collapsed, blocking the river for three days; the river water dried up.", idiomatic: "In spring, the first month, on bingyin, Mount Min in Shu Commandery collapsed, blocking the river for three days; the river water dried up." },
  { zh: "劉向大惡之，曰：「昔周岐山崩，三川竭，而幽王亡。", literal: "Liu Xiang greatly detested it and said: \"Formerly when Zhou's Mount Qi collapsed and the Three Rivers dried up, King You perished.", idiomatic: "Liu Xiang greatly detested it and said, \"Formerly when Zhou's Mount Qi collapsed and the Three Rivers dried up, King You perished." },
  { zh: "岐山者，周所興也。", literal: "Mount Qi was where Zhou rose.", idiomatic: "Mount Qi was where Zhou rose." },
  { zh: "漢家本起於蜀、漢，今所起之地，山崩川竭，星孛又及攝提、大角，從參至辰，殆必亡矣！", literal: "The House of Han originally rose from Shu and Han; now in the place where it rose, mountains collapse and rivers dry up; the broom star again reaches Sheti and Dajiao, from Shen to Chen—almost certainly it must perish!", idiomatic: "The House of Han originally rose from Shu and Han; now in the place where it rose, mountains collapse and rivers dry up; the broom star again reaches Sheti and Dajiao, from Shen to Chen—almost certainly it must perish!" },
  { zh: "二月，丙午，封淳于長為定陵侯。", literal: "In the second month, on bingwu, Chunyu Chang was enfeoffed as Marquis of Dingling.", idiomatic: "In the second month, on bingwu, Chunyu Chang was enfeoffed as Marquis of Dingling." },
  { zh: "三月，上行幸雍，祠五畤。", literal: "In the third month, the emperor traveled to Yong and sacrificed at the Five Altars.", idiomatic: "In the third month, the emperor traveled to Yong and sacrificed at the Five Altars." },
  { zh: "上將大誇胡人以多禽獸。", literal: "The emperor was about to greatly boast to the Hu people that there were many birds and beasts.", idiomatic: "The emperor was about to greatly boast to the Hu people that there were many birds and beasts." },
  { zh: "秋，命右扶風發民入南山，西自褒、斜，東至弘農，南驅漢中，張羅罔罝罘，捕熊羆禽獸，載以檻車，輸長楊射熊館，以罔為周阹，縱禽獸其中，令胡人手搏之，自取其獲，上親臨觀焉。", literal: "In autumn, he ordered Right Fufeng to mobilize the people into the southern mountains—from the west from Bao and Xie, east to Hongnong, south driving into Hanzhong—spreading nets, spring-traps, and bag-nets, capturing bears and birds and beasts, loading them in cage-carts and transporting them to the Bear-Shooting Lodge at Changyang; with nets he made an encircling park, released the birds and beasts within, ordered Hu men to wrestle them hand to hand and take their own catch, and the emperor personally came to observe.", idiomatic: "In autumn, he ordered Right Fufeng to mobilize the people into the southern mountains—from the west from Bao and Xie, east to Hongnong, south driving into Hanzhong—spreading nets, spring-traps, and bag-nets, capturing bears and birds and beasts, loading them in cage-carts and transporting them to the Bear-Shooting Lodge at Changyang; with nets he made an encircling park, released the birds and beasts within, ordered Hu men to wrestle them hand to hand and take their own catch, and the emperor personally came to observe." },
  { zh: "春，正月，上行幸甘泉，郊泰畤。", literal: "In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar.", idiomatic: "In spring, the first month, the emperor traveled to Sweet Springs and sacrificed at the Great Altar." },
  { zh: "中山王興，定陶王欣皆來朝，中山王獨從傅，定陶王盡從傅、相、中尉。", literal: "King Xing of Zhongshan and King Xin of Dingtao both came to court; the King of Zhongshan alone followed his tutor, while the King of Dingtao fully followed his tutor, chancellor, and chief commandant.", idiomatic: "King Xing of Zhongshan and King Xin of Dingtao both came to court; the King of Zhongshan alone followed his tutor, while the King of Dingtao fully followed his tutor, chancellor, and chief commandant." },
  { zh: "上怪之，以問定陶王，對曰：「令：諸侯王朝，得從其國二千石。", literal: "The emperor thought it strange and questioned the King of Dingtao; he replied: \"The ordinance: when feudal kings attend court, they may follow their state's 2,000-bushel officials.", idiomatic: "The emperor thought it strange and questioned the King of Dingtao; he replied, \"The ordinance: when feudal kings attend court, they may follow their state's 2,000-bushel officials." },
  { zh: "傅、相、中尉，皆國二千石，故盡從之。", literal: "The tutor, chancellor, and chief commandant are all state 2,000-bushel officials—therefore I fully followed them.", idiomatic: "The tutor, chancellor, and chief commandant are all state 2,000-bushel officials—therefore I fully followed them." },
  { zh: "」上令誦《詩》，通習，能說。", literal: "\" The emperor ordered him to recite the Odes; he was thoroughly practiced and could expound.", idiomatic: "\" The emperor ordered him to recite the Odes; he was thoroughly practiced and could expound." },
  { zh: "佗日，問中山王：「獨從傅在何法令？", literal: "Another day he asked the King of Zhongshan: \"Following the tutor alone—under what ordinance?", idiomatic: "Another day he asked the King of Zhongshan, \"Following the tutor alone—under what ordinance?" },
  { zh: "」不能對；", literal: "\" He could not answer;", idiomatic: "\" He could not answer;" },
  { zh: "令誦《尚書》，又廢；", literal: "ordered to recite the Documents, he again failed;", idiomatic: "ordered to recite the Documents, he again failed;" },
  { zh: "及賜食於前，後飽；", literal: "when food was granted before him, he ate after he was full;", idiomatic: "when food was granted before him, he ate after he was full;" },
  { zh: "起下，襪系解。", literal: "rising and stepping down, his sock ties came undone.", idiomatic: "rising and stepping down, his sock ties came undone." },
  { zh: "帝由此以為不能，而賢定陶王，數稱其材。", literal: "The emperor thereby considered him incapable, but esteemed the King of Dingtao and repeatedly praised his talent.", idiomatic: "The emperor thereby considered him incapable, but esteemed the King of Dingtao and repeatedly praised his talent." },
  { zh: "是時諸侯王唯二人於帝為至親，定陶王祖母傅太后隨王來朝，私賂遺趙皇后、昭儀及票騎將軍王根。", literal: "At this time among the feudal kings only these two were the emperor's closest kin; the King of Dingtao's grandmother, Empress Dowager Fu, followed the king to court and privately bribed and sent gifts to Empress Zhao, the Brilliant Companion, and Rapid Cavalry General Wang Gen.", idiomatic: "At this time among the feudal kings only these two were the emperor's closest kin; the King of Dingtao's grandmother, Empress Dowager Fu, followed the king to court and privately bribed and sent gifts to Empress Zhao, the Brilliant Companion, and Rapid Cavalry General Wang Gen." },
  { zh: "后、昭儀、根見上無子，亦欲豫自結，為長久計，皆更稱定陶王，勸帝以為嗣。", literal: "The empress, Brilliant Companion, and Gen, seeing the emperor had no son, also wished to bind themselves in advance for a long-term plan; all changed to praise the King of Dingtao and urged the emperor to make him heir.", idiomatic: "The empress, Brilliant Companion, and Gen, seeing the emperor had no son, also wished to bind themselves in advance for a long-term plan; all changed to praise the King of Dingtao and urged the emperor to make him heir." },
  { zh: "帝亦自美其材，為加元服而遣之，時年十七矣。", literal: "The emperor also himself praised his talent, performed the capping ceremony for him, and sent him away—he was then seventeen.", idiomatic: "The emperor also himself praised his talent, performed the capping ceremony for him, and sent him away—he was then seventeen." },
  { zh: "三月，上行幸河東，祠后土。", literal: "In the third month, the emperor traveled to Hedong and sacrificed to the Earth Queen.", idiomatic: "In the third month, the emperor traveled to Hedong and sacrificed to the Earth Queen." },
  { zh: "隕石於關東二。", literal: "Two meteorites fell in the eastern passes.", idiomatic: "Two meteorites fell in the eastern passes." },
  { zh: "王根薦谷永，征入，為大司農。", literal: "Wang Gen recommended Gu Yong; he was summoned in and made Minister of the Masses.", idiomatic: "Wang Gen recommended Gu Yong; he was summoned in and made Minister of the Masses." },
  { zh: "永前後所上四十餘事，略相反覆，專攻上身與後宮而已；", literal: "Yong's more than forty submissions before and after were roughly contradictory and repetitive, attacking only the emperor's person and the inner palace;", idiomatic: "Yong's more than forty submissions before and after were roughly contradictory and repetitive, attacking only the emperor's person and the inner palace;" },
  { zh: "黨於王氏，上亦知之，不甚親信也。", literal: "he sided with the Wang clan; the emperor also knew this and did not greatly trust him.", idiomatic: "he sided with the Wang clan; the emperor also knew this and did not greatly trust him." },
  { zh: "為大司農歲餘，病；", literal: "After more than a year as Minister of the Masses, he fell ill;", idiomatic: "After more than a year as Minister of the Masses, he fell ill;" },
  { zh: "滿三月，上不賜告，即時免。", literal: "when three months were full, the emperor did not grant leave and immediately dismissed him.", idiomatic: "when three months were full, the emperor did not grant leave and immediately dismissed him." },
  { zh: "數月，卒。", literal: "Several months later, he died.", idiomatic: "Several months later, he died." },
  { zh: "春，正月，大赦天下。", literal: "In spring, the first month, there was a great amnesty for the empire.", idiomatic: "In spring, the first month, there was a great amnesty for the empire." },
  { zh: "上召丞相翟方進、御史大夫孔光、右將軍廉褒、後將軍朱博入禁中，議「中山、定陶王誰宜為嗣者」。", literal: "The emperor summoned Chancellor Zhai Fangjin, Censor-in-Chief Kong Guang, Right General Lian Bao, and Rear General Zhu Bo into the inner palace to deliberate \"which of the Kings of Zhongshan and Dingtao ought to be heir.\"", idiomatic: "The emperor summoned Chancellor Zhai Fangjin, Censor-in-Chief Kong Guang, Right General Lian Bao, and Rear General Zhu Bo into the inner palace to deliberate \"which of the Kings of Zhongshan and Dingtao ought to be heir.\"" },
  { zh: "方進、根、褒、博皆以為：「定陶王，帝弟之子，《禮》曰：『昆弟之子，猶子也。", literal: "Fangjin, Gen, Bao, and Bo all considered: \"The King of Dingtao is the emperor's younger brother's son. The Rites says: 'A brother's son is like a son.", idiomatic: "Fangjin, Gen, Bao, and Bo all considered, \"The King of Dingtao is the emperor's younger brother's son. The Rites says, 'A brother's son is like a son." },
  { zh: "為其後者，為之子也，』定陶王宜為嗣。", literal: "Who continues his line is his son'—the King of Dingtao ought to be heir.", idiomatic: "Who continues his line is his son'—the King of Dingtao ought to be heir." },
  { zh: "」光獨以為：「禮，立嗣以親。", literal: "\" Guang alone considered: \"By ritual, one establishes an heir by closeness.", idiomatic: "\" Guang alone considered, \"By ritual, one establishes an heir by closeness." },
  { zh: "以《尚書‧盤庚》殷之及王為比，兄終弟及。", literal: "Taking the passage in the Documents, 'Pangeng,' comparing Yin and its reaching kings—elder brother ends, younger brother succeeds.", idiomatic: "Taking the passage in the Documents, 'Pangeng,' comparing Yin and its reaching kings—elder brother ends, younger brother succeeds." },
  { zh: "中山王，先帝之子，帝親弟，宜為嗣。", literal: "The King of Zhongshan is the former emperor's son, the emperor's younger brother by blood—he ought to be heir.", idiomatic: "The King of Zhongshan is the former emperor's son, the emperor's younger brother by blood—he ought to be heir." },
  { zh: "」上以「中山王不材；", literal: "\" The emperor, on the grounds that \"the King of Zhongshan lacks talent;", idiomatic: "\" The emperor, on the grounds that \"the King of Zhongshan lacks talent;" },
  { zh: "又禮，兄弟不得相入廟，」不從光議。", literal: "and again by ritual brothers may not enter one another's temples,\" did not follow Guang's proposal.", idiomatic: "and again by ritual brothers may not enter one another's temples,\" did not follow Guang's proposal." },
  { zh: "二月，癸丑，詔立定陶王欣為皇太子，封中山王舅諫大夫馮參為宜鄉侯，益中山國三萬戶，以慰其意；", literal: "In the second month, on guichou, an edict established King Xin of Dingtao as heir apparent, enfeoffed the King of Zhongshan's maternal uncle Remonstrance Grandee Feng Can as Marquis of Yixiang, and increased Zhongshan state by thirty thousand households to console his intent;", idiomatic: "In the second month, on guichou, an edict established King Xin of Dingtao as heir apparent, enfeoffed the King of Zhongshan's maternal uncle Remonstrance Grandee Feng Can as Marquis of Yixiang, and increased Zhongshan state by thirty thousand households to console his intent;" },
  { zh: "使執金吾任宏守大鴻臚，持節征定陶王。", literal: "he sent Bearer of the Mace Ren Hong to hold office as Grand Herald and, bearing credentials, summon the King of Dingtao.", idiomatic: "he sent Bearer of the Mace Ren Hong to hold office as Grand Herald and, bearing credentials, summon the King of Dingtao." },
  { zh: "定陶王謝曰：「臣材質不足以假充太子之宮；", literal: "The King of Dingtao declined, saying: \"Your servant's substance and quality are insufficient to borrow and fill the heir apparent's palace;", idiomatic: "The King of Dingtao declined, saying, \"Your servant's substance and quality are insufficient to borrow and fill the heir apparent's palace;" },
  { zh: "臣願且得留國邸，旦夕奉問起居，俟有聖嗣，歸國守籓。", literal: "your servant wishes for the time being to remain at the state lodge, morning and evening attending to inquire after health; when there is a sage successor, return to the state and guard the frontier.", idiomatic: "your servant wishes for the time being to remain at the state lodge, morning and evening attending to inquire after health; when there is a sage successor, return to the state and guard the frontier." },
  { zh: "」書奏，天子報聞。", literal: "\" When the memorial was submitted, the Son of Heaven acknowledged receipt.", idiomatic: "\" When the memorial was submitted, the Son of Heaven acknowledged receipt." },
  { zh: "戊午，孔光以議不合意，左遷廷尉；", literal: "On wuwu, Kong Guang, because his proposal did not accord with the intent, was demoted to be Commandant of Justice;", idiomatic: "On wuwu, Kong Guang, because his proposal did not accord with the intent, was demoted to be Commandant of Justice;" },
  { zh: "何武為御史大夫。", literal: "He Wu was made Censor-in-Chief.", idiomatic: "He Wu was appointed Censor-in-Chief." },
  { zh: "初，詔求殷後，分散為十餘姓，推求其嫡，不能得。", literal: "Earlier, an edict sought a descendant of the Yin, scattered into more than ten surnames; tracing for the direct line, none could be found.", idiomatic: "Earlier, an edict had sought a descendant of the Yin, but the line was scattered among more than ten surnames and no direct heir could be found." },
  { zh: "匡衡、梅福皆以為宜封孔子世為湯後，上從之，封孔吉為殷紹嘉侯。", literal: "Kuang Heng and Mei Fu all held that it was fitting to enfeoff Confucius's lineage as successor to Tang; the emperor followed this and enfeoffed Kong Ji as Marquis Who Continues and Glorifies the Yin.", idiomatic: "Kuang Heng and Mei Fu both argued that Confucius's lineage should be enfeoffed as successor to Tang; the emperor agreed and enfeoffed Kong Ji as Marquis Who Continues and Glorifies the Yin." },
  { zh: "三月，與周承休侯皆進爵為公，地各百里。", literal: "In the third month, he and the Marquis Who Inherits and Rests Zhou were both advanced in rank to duke, each with a fief of a hundred li.", idiomatic: "In the third month, he and the Marquis Who Inherits and Rests Zhou were both promoted to duke, each with a fief of a hundred li." },
  { zh: "上行幸雍，祠五畤。", literal: "The emperor traveled in person to Yong and sacrificed at the Five Altars.", idiomatic: "The emperor traveled to Yong and sacrificed at the Five Altars." },
  { zh: "初，何武之為廷尉也，建言：「末俗之敝，政事煩多，宰相之材不能及古，而丞相獨兼三公之事，所以久廢而不治也。", literal: "Earlier, when He Wu was Commandant of Justice, he submitted a proposal: \"The abuses of decadent custom—government affairs are numerous and vexing; the talent of chancellors cannot match antiquity, yet the Chancellor alone combines the affairs of the Three Ducal Lords—this is why things have long lain neglected and ungoverned.", idiomatic: "Earlier, when He Wu was Commandant of Justice, he proposed, \"Decadent custom has made government affairs numerous and vexing; chancellors no longer match those of antiquity, yet the Chancellor alone still combines the duties of the Three Ducal Lords—this is why affairs have long lain neglected and ungoverned." },
  { zh: "宜建三公官。", literal: "It is fitting to establish the offices of the Three Ducal Lords.", idiomatic: "The Three Ducal offices ought to be established." },
  { zh: "」上從之。", literal: "\" The emperor followed this.", idiomatic: "\" The emperor agreed." },
  { zh: "夏，四月，賜曲陽侯根大司馬印綬，置官屬，罷票騎將軍官；", literal: "In summer, the fourth month, he bestowed on Marquis Gen of Quyang the seal and cord of Grand Marshal, established official staff, and abolished the office of Rapid Cavalry General;", idiomatic: "In summer, the fourth month, he bestowed on Marquis Gen of Quyang the Grand Marshal's seal and cord, established his staff, and abolished the office of Rapid Cavalry General;" },
  { zh: "以御史大夫何武為大司空，封汜鄉侯。", literal: "he made Censor-in-Chief He Wu Grand Minister of Works and enfeoffed him as Marquis of Siziang.", idiomatic: "he appointed Censor-in-Chief He Wu Grand Minister of Works and enfeoffed him as Marquis of Siziang." },
  { zh: "皆增奉如丞相，以備三公焉。", literal: "All had their salaries increased to match the Chancellor's, to complete the Three Ducal Lords.", idiomatic: "All received salaries raised to match the Chancellor's, completing the Three Ducal Lords." },
  { zh: "秋，八月，庚戌，中山孝王興薨。", literal: "In autumn, the eighth month, on gengxu, King Xiao of Zhongshan Xing died.", idiomatic: "In autumn, the eighth month, on gengxu, King Xiao of Zhongshan Xing died." },
  { zh: "匈奴車牙單于死；", literal: "The Xiongnu Chanyu Cheya died;", idiomatic: "The Xiongnu Chanyu Cheya died;" },
  { zh: "弟囊知牙斯立，為烏珠留若鞮單于。", literal: "his younger brother Nangzhi Yasi was installed as Chanyu Wuzhuliu Ruodi.", idiomatic: "his younger brother Nangzhi Yasi was installed as Chanyu Wuzhuliu Ruodi." },
  { zh: "烏珠留單于立，以弟樂為左賢王，輿為右賢王，漢遣中郎將夏侯籓、副校尉韓容使匈奴。", literal: "When Chanyu Wuzhuliu was installed, he made his younger brother Yue Left Worthy King and Yu Right Worthy King; Han sent Gentlemen-of-the-House Xiahou Fan and Assistant Commandant Han Rong as envoys to the Xiongnu.", idiomatic: "When Chanyu Wuzhuliu took the throne, he made his younger brother Yue Left Worthy King and Yu Right Worthy King; Han sent Gentlemen-of-the-House Xiahou Fan and Assistant Commandant Han Rong as envoys to the Xiongnu." },
  { zh: "或說王根曰：「匈奴有斗入漢地，直張掖郡，生奇材木箭竿，鷲羽；", literal: "Someone urged Wang Gen, saying: \"The Xiongnu have a wedge of land thrusting into Han territory, pointing straight at Zhangye commandery, producing marvelous timber for arrow shafts and vulture feathers;", idiomatic: "Someone urged Wang Gen, saying, \"The Xiongnu hold a wedge of land thrusting into Han territory toward Zhangye commandery, producing fine timber for arrow shafts and vulture feathers;" },
  { zh: "如得之，於邊甚饒，國家有廣地之實，將軍顯功垂於無窮！", literal: "if it were obtained, the border would be greatly enriched, the state would have the substance of broadened territory, and the general's illustrious merit would extend to endless ages!", idiomatic: "if it were obtained, the border would be greatly enriched, the state would gain broad territory, and the general's merit would endure forever!" },
  { zh: "」根為上言其利，上直欲從單于求之，為有不得，傷命損威。", literal: "\" Gen reported its benefit to the emperor; the emperor wished to seek it directly from the Chanyu, but lest he not obtain it and harm life and diminish prestige—", idiomatic: "\" Gen reported the benefit to the emperor; the emperor wished to seek it directly from the Chanyu, but feared failure would cost lives and diminish prestige." },
  { zh: "根即但以上指曉籓，令從籓所說而求之。", literal: "Gen thereupon only used the emperor's intent to instruct Fan, ordering him to seek it as Fan had proposed.", idiomatic: "Gen thereupon only conveyed the emperor's intent to Fan and ordered him to seek the land as Fan had proposed." },
  { zh: "籓至匈奴，以語次說單于曰：「竊見匈奴斗入漢地，直張掖郡，漢三都尉居塞上，士卒數百人，寒苦，候望久勞，單于宜上書獻此地，直斷割之，省兩都尉士卒數百人，以復天子厚恩，其報必大。", literal: "When Fan reached the Xiongnu, he took occasion in conversation to urge the Chanyu, saying: \"Your subject observes that the Xiongnu wedge into Han land points straight at Zhangye commandery; Han's three commandants dwell on the frontier with several hundred soldiers, suffering cold and hardship, long worn with watch and ward—the Chanyu ought to submit a memorial offering this land and cut it off straight away, sparing the two commandants several hundred soldiers, to repay the Son of Heaven's thick grace; the return must be great.", idiomatic: "When Fan reached the Xiongnu, he took occasion in conversation to urge the Chanyu, saying, \"Your subject observes that the Xiongnu wedge into Han land points straight at Zhangye; Han's three frontier commandants keep several hundred soldiers there in cold and hardship, long worn with watch and ward—the Chanyu ought to submit a memorial offering this land and cut it off outright, sparing the two commandants several hundred soldiers, to repay the Son of Heaven's great grace; the return would be great." },
  { zh: "」單于曰：「此天子詔語邪，將從使者所求也？", literal: "\" The Chanyu said: \"Is this the Son of Heaven's edict language, or is it what the envoy seeks?", idiomatic: "\" The Chanyu said, \"Is this the Son of Heaven's edict, or what the envoy seeks?" },
  { zh: "」籓曰：「詔指也；", literal: "\" Fan said: \"It is the edict's intent;", idiomatic: "\" Fan said, \"It is the edict's intent;" },
  { zh: "然籓亦為單于畫善計耳。", literal: "yet Fan also draws a good plan for the Chanyu.", idiomatic: "yet Fan is also drawing a good plan for the Chanyu." },
  { zh: "」單于曰：「此溫偶駼王所居地也，未曉其形狀、所生，請遣使問之。", literal: "\" The Chanyu said: \"This is land where King Wen'ou Tuo dwells; I do not yet know its shape and what it produces—please send an envoy to inquire.", idiomatic: "\" The Chanyu said, \"This is land where King Wen'ou Tuo dwells; I do not yet know its terrain and products—please send an envoy to inquire." },
  { zh: "」籓、容歸漢；", literal: "\" Fan and Rong returned to Han;", idiomatic: "\" Fan and Rong returned to Han;" },
  { zh: "後復使匈奴，至則求地。", literal: "later they were again sent to the Xiongnu, and on arrival sought the land.", idiomatic: "later they were again sent to the Xiongnu and on arrival sought the land." },
  { zh: "單于曰：「父兄傳五世，漢不求此地，至知獨求，何也？", literal: "The Chanyu said: \"Father and elder brother transmitted it for five generations; Han did not seek this land—why does Zhi alone seek it now?", idiomatic: "The Chanyu said, \"Father and elder brother transmitted it for five generations; Han never sought this land—why does Zhi alone seek it now?" },
  { zh: "已問溫偶駼王，匈奴西邊諸侯作穹廬及車，皆仰此山材木，且先父地，不敢失也。", literal: "I have already asked King Wen'ou Tuo: the Xiongnu western frontier lords who make yurts and carts all rely on this mountain's timber; moreover it is our forefathers' land—I dare not lose it.", idiomatic: "I have already asked King Wen'ou Tuo: the western frontier lords who make yurts and carts all rely on this mountain's timber; moreover it is our forefathers' land—I dare not lose it." },
  { zh: "」籓還，遷為太原太守。", literal: "\" Fan returned and was transferred to be Administrator of Taiyuan.", idiomatic: "\" Fan returned and was transferred to Administrator of Taiyuan." },
  { zh: "單于遣使上書，以籓求地狀聞。", literal: "The Chanyu sent an envoy with a memorial reporting how Fan had sought the land.", idiomatic: "The Chanyu sent an envoy with a memorial reporting Fan's attempt to seek the land." },
  { zh: "詔報單于曰：「籓擅稱詔，從單于求地，法當死；", literal: "An edict replied to the Chanyu, saying: \"Fan presumptuously claimed an edict and sought land from the Chanyu—by law he should die;", idiomatic: "An edict replied to the Chanyu, saying, \"Fan presumptuously claimed an edict and sought land from the Chanyu—by law he should die;" },
  { zh: "更大赦二，令徙籓為濟南太守，不令當匈奴。", literal: "there have been two more great amnesties; he is ordered transferred to be Administrator of Jinan and not permitted to face the Xiongnu.", idiomatic: "there have been two more great amnesties; he is transferred to Administrator of Jinan and not permitted to face the Xiongnu again." },
  { zh: "冬，十月，甲寅，王根病免。", literal: "In winter, the tenth month, on jiayin, Wang Gen resigned on account of illness.", idiomatic: "In winter, the tenth month, on jiayin, Wang Gen resigned on account of illness." },
  { zh: "上以太子既奉大宗後，不得顧私親，十一月，立楚孝王孫景為定陶王，以奉恭王後。", literal: "Because the heir apparent already served the great lineage as successor and could not attend to private kin, in the eleventh month he installed Jing, grandson of King Xiao of Chu, as King of Dingtao to continue King Gong's line.", idiomatic: "Because the heir apparent already served the great lineage and could not attend to private kin, in the eleventh month he installed Jing, grandson of King Xiao of Chu, as King of Dingtao to continue King Gong's line." },
  { zh: "太子議欲謝；", literal: "The heir apparent deliberated and wished to decline thanks;", idiomatic: "The heir apparent deliberated and wished to decline thanks;" },
  { zh: "少傅閻崇以為為人後之禮，不得顧私親，不當謝；", literal: "Junior Tutor Yan Chong held that by the rites of becoming another's successor one may not attend to private kin and ought not to decline thanks;", idiomatic: "Junior Tutor Yan Chong held that by the rites of adoption one may not attend to private kin and ought not to decline thanks;" },
  { zh: "太傅趙玄以為當謝，太子從之。", literal: "Grand Tutor Zhao Xuan held that he ought to decline thanks; the heir apparent followed this.", idiomatic: "Grand Tutor Zhao Xuan held that he ought to decline thanks; the heir apparent followed him." },
  { zh: "詔問所以謝狀，尚書劾奏玄，左遷少府；", literal: "An edict inquired the grounds for declining thanks; the Master of Documents impeached Xuan and demoted him to Minister Steward;", idiomatic: "An edict inquired the grounds for declining thanks; the Master of Documents impeached Xuan and demoted him to Minister Steward;" },
  { zh: "以光祿勳師丹為太傅。", literal: "Grand Master of Splendor Shi Dan was made Grand Tutor.", idiomatic: "Grand Master of Splendor Shi Dan was made Grand Tutor." },
  { zh: "初，太子之幼也，王祖母傅太后躬自養視；", literal: "Earlier, when the heir apparent was young, his paternal grandmother Empress Dowager Fu personally reared and watched over him;", idiomatic: "Earlier, when the heir apparent was young, his paternal grandmother Empress Dowager Fu personally reared him;" },
  { zh: "及為太子，詔傅太后與太子母丁姬自居定陶國邸，不得相見。", literal: "when he became heir apparent, an edict ordered Empress Dowager Fu and the heir apparent's mother Lady Ding to dwell separately at the Dingtao state residence and not to meet.", idiomatic: "when he became heir apparent, an edict ordered Empress Dowager Fu and the heir apparent's mother Lady Ding to dwell separately at the Dingtao state residence and not to meet." },
  { zh: "頃之，王太后欲令傅太后、丁姬十日一至太子家，帝曰：「太子承正統，當共養陛下，不得復顧私親。", literal: "Shortly after, Empress Dowager Wang wished to let Empress Dowager Fu and Lady Ding come once every ten days to the heir apparent's residence; the emperor said: \"The heir apparent inherits the orthodox succession and ought jointly to nurture Your Majesty—he may not again attend to private kin.", idiomatic: "Shortly after, Empress Dowager Wang wished to let Empress Dowager Fu and Lady Ding visit the heir apparent's residence once every ten days; the emperor said, \"The heir apparent inherits the orthodox succession and ought jointly to nurture Your Majesty—he may not again attend to private kin." },
  { zh: "」王太后曰：「太子小而傅太后抱養之；", literal: "\" Empress Dowager Wang said: \"When the heir apparent was small, Empress Dowager Fu held and reared him;", idiomatic: "\" Empress Dowager Wang said, \"When the heir apparent was small, Empress Dowager Fu held and reared him;" },
  { zh: "今至太子家，以乳母恩耳，不足有所妨。", literal: "now to come to the heir apparent's residence is merely wet-nurse affection—insufficient to cause any hindrance.", idiomatic: "now to visit the heir apparent's residence is merely wet-nurse affection—nothing to hinder." },
  { zh: "」於是令傅太后得至太子家；", literal: "\" Thereupon he ordered that Empress Dowager Fu might come to the heir apparent's residence;", idiomatic: "\" Thereupon he allowed Empress Dowager Fu to visit the heir apparent's residence;" },
  { zh: "丁姬以不養太子，獨不得。", literal: "Lady Ding, because she had not reared the heir apparent, alone was not permitted.", idiomatic: "Lady Ding alone was not permitted, because she had not reared the heir apparent." },
  { zh: "衛尉、侍中淳于長有寵於上，大見信用，貴傾公卿，外交諸侯、牧、守，賂遺、賞賜累巨萬，淫於聲色。", literal: "Defender of the Palace and Attendant-in-Ordinary Chunyu Chang had the emperor's favor, was greatly trusted, his nobility overwhelming the grandees; outwardly he associated with feudal lords, governors, and administrators; bribes and gifts and rewards accumulated to tens of millions; he was dissolute in sound and color.", idiomatic: "Defender of the Palace and Attendant-in-Ordinary Chunyu Chang enjoyed the emperor's favor and great trust; his prestige overwhelmed the grandees; he associated with feudal lords, governors, and administrators; bribes, gifts, and rewards totaled tens of millions; he was dissolute in pleasures." },
  { zh: "許後姊孊為龍雒思侯夫人，寡居；", literal: "Empress Xu's elder sister Yan was wife of the Marquis of Longluosi and lived as a widow;", idiomatic: "Empress Xu's elder sister Yan was wife of the Marquis of Longluosi and lived as a widow;" },
  { zh: "長與孊私通，因取為小妻。", literal: "Chang had a secret liaison with Yan and thereupon took her as a secondary wife.", idiomatic: "Chang had a secret affair with Yan and took her as a secondary wife." },
  { zh: "許後時居長定宮，因孊賂遺長，欲求復為婕妤。", literal: "Empress Xu then dwelt at Changding Palace; through Yan she bribed Chang, seeking to be restored as Lady of Handsome Fairness.", idiomatic: "Empress Xu then dwelt at Changding Palace; through Yan she bribed Chang, seeking restoration as Lady of Handsome Fairness." },
  { zh: "長受許後金錢、乘輿、服御物前後千餘萬，詐許為白上，立以為左皇后。", literal: "Chang received from Empress Xu gold, money, imperial carriages, and apparel and furnishings totaling more than ten million over time, falsely promising to report to the emperor and have her installed as Left Empress.", idiomatic: "Chang received from Empress Xu gold, money, imperial carriages, and furnishings totaling more than ten million over time, falsely promising to report to the emperor and have her installed as Left Empress." },
  { zh: "孊每入長定宮，輒與孊書，戲侮許後，嫚易無不言；", literal: "Whenever Yan entered Changding Palace, she would exchange letters with Yan, mocking and insulting Empress Xu, contemptuous and insolent in all she said;", idiomatic: "Whenever Yan entered Changding Palace, she exchanged letters with Yan mocking and insulting Empress Xu, contemptuous in all she said;" },
  { zh: "交通書記，賂遺連年。", literal: "they exchanged written communications and bribes year after year.", idiomatic: "they exchanged letters and bribes year after year." },
  { zh: "時曲陽侯根輔政，久病，數乞骸骨。", literal: "At the time Marquis Gen of Quyang assisted in government, was long ill, and repeatedly begged to resign his bones.", idiomatic: "At the time Marquis Gen of Quyang was assisting in government, had been long ill, and repeatedly asked to resign." },
  { zh: "長以外親居九卿位，次第當代根。", literal: "Chang, as a maternal relative holding a Nine Ministers post, was next in order to replace Gen.", idiomatic: "Chang, as a maternal relative in a Nine Ministers post, was next in line to replace Gen." },
  { zh: "侍中、騎都尉、光祿大夫王莽心害長寵，私聞其事。", literal: "Attendant-in-Ordinary, Commandant of Cavalry, and Grand Master of Splendor Wang Mang inwardly resented Chang's favor and privately heard of these matters.", idiomatic: "Attendant-in-Ordinary, Commandant of Cavalry, and Grand Master of Splendor Wang Mang resented Chang's favor and privately learned of these matters." },
  { zh: "莽侍曲陽侯病，因言：「長見將軍久病意喜，自以當代輔政，至對及冠議語署置。", literal: "Mang attended Gen in his illness and thereupon said: \"Chang, seeing the general's long illness, was pleased at heart, thinking himself about to replace him in assisting government—even to the point of answering and discussing caps and speech and appointments.", idiomatic: "Mang attended Gen in his illness and said, \"Chang, seeing the general's long illness, was pleased, thinking himself about to replace him in government—even discussing caps, speech, and appointments." },
  { zh: "」具言其罪過。", literal: "\" He fully stated his crimes and faults.", idiomatic: "\" He fully stated his crimes." },
  { zh: "根怒曰：「即如是，何不白也」？", literal: "Gen angrily said: \"If it is so, why not report it?\"", idiomatic: "Gen angrily said, \"If it is so, why not report it?\"" },
  { zh: "莽曰：「未知將軍意，故未敢言！", literal: "Mang said: \"Not knowing the general's intent, I did not dare speak!", idiomatic: "Mang said, \"Not knowing the general's intent, I did not dare speak!" },
  { zh: "」根曰：「趣白東宮！", literal: "\" Gen said: \"Hurry and report to the Eastern Palace!\"", idiomatic: "\" Gen said, \"Hurry and report to the Eastern Palace!\"" },
  { zh: "」莽求見太后，具言長驕佚，欲代曲陽侯；", literal: "\" Mang sought audience with the Empress Dowager and fully stated that Chang was arrogant and dissolute and wished to replace the Marquis of Quyang;", idiomatic: "\" Mang sought audience with the Empress Dowager and fully reported that Chang was arrogant and dissolute and wished to replace the Marquis of Quyang;" },
  { zh: "私與長定貴人姊通，受取其衣物。", literal: "he had secretly liaised with the elder sister of the Lady of Changding and received her clothing.", idiomatic: "he had secretly liaised with the elder sister of the Lady of Changding and taken her clothing." },
  { zh: "太后亦怒曰：「兒至如此！", literal: "The Empress Dowager also angrily said: \"The boy has come to this!", idiomatic: "The Empress Dowager also angrily said, \"The boy has come to this!" },
  { zh: "往，白之帝！", literal: "Go—report it to the emperor!", idiomatic: "Go—report it to the emperor!" },
  { zh: "」莽白上；", literal: "\" Mang reported to the emperor;", idiomatic: "\" Mang reported to the emperor;" },
  { zh: "上以太后故，免長官，勿治罪，遣就國。", literal: "because of the Empress Dowager, the emperor removed Chang from office, did not punish him, and sent him to his state.", idiomatic: "because of the Empress Dowager, the emperor removed Chang from office, did not punish him, and sent him to his fief." },
  { zh: "初，紅陽侯立不得輔政，疑為長毀譖，常怨毒長；", literal: "Earlier, Marquis Li of Hongyang, not obtaining a role in government, suspected Chang of slandering him and constantly bore bitter hatred toward Chang;", idiomatic: "Earlier, Marquis Li of Hongyang, denied a role in government, suspected Chang of slandering him and constantly hated him;" },
  { zh: "上知之。", literal: "the emperor knew this.", idiomatic: "the emperor knew this." },
  { zh: "及長當就國，立嗣子融從長請車騎，長以珍寶因融重遺立。", literal: "When Chang was about to go to his state, Li's heir Rong followed Chang to request chariots and horsemen; Chang used treasures through Rong to send a heavy gift again to Li.", idiomatic: "When Chang was about to depart for his fief, Li's heir Rong followed Chang to request chariots and escort; Chang sent a heavy gift of treasures to Li through Rong." },
  { zh: "立因上封事，為長求留，曰：「陛下既托文以皇太后故，誠不可更有它計。", literal: "Li thereupon submitted a sealed memorial seeking to retain Chang, saying: \"Your Majesty has already entrusted the matter to writing on account of the Empress Dowager—truly there must not be another plan.", idiomatic: "Li thereupon submitted a sealed memorial seeking to retain Chang, saying, \"Your Majesty has already committed in writing on account of the Empress Dowager—there truly must not be another plan." },
  { zh: "」於是天子疑焉，下有司按驗。", literal: "\" Thereupon the Son of Heaven grew suspicious and sent it down to the responsible offices for investigation and verification.", idiomatic: "\" Thereupon the emperor grew suspicious and ordered the responsible offices to investigate." },
  { zh: "吏捕融，立令融自殺以滅口。", literal: "Officials arrested Rong; Li ordered Rong to kill himself to silence him.", idiomatic: "Officials arrested Rong; Li ordered Rong to kill himself to silence him." },
  { zh: "上愈疑其有大奸，遂逮長系洛陽詔獄，窮治。", literal: "The emperor grew still more suspicious of great treachery and thereupon arrested Chang and imprisoned him in the Luoyang imperial prison, investigating to the end.", idiomatic: "The emperor grew still more suspicious of great treachery and arrested Chang, imprisoning him in the Luoyang imperial prison for a full investigation." },
  { zh: "長具服戲侮長定宮，謀立左皇后，罪至大逆，死獄中。", literal: "Chang fully confessed to mocking Changding Palace and plotting to install a Left Empress—crime reaching great treason; he died in prison.", idiomatic: "Chang fully confessed to mocking Changding Palace and plotting to install a Left Empress—crime reaching great treason; he died in prison." },
  { zh: "妻子當坐者徙合浦；", literal: "Wife and children who should share punishment were exiled to Hepu;", idiomatic: "Wife and children who shared punishment were exiled to Hepu;" },
  { zh: "母若歸故郡。", literal: "his mother Ru returned to her native commandery.", idiomatic: "his mother Ru returned to her native commandery." },
  { zh: "上使廷尉孔光持節賜廢後藥，自殺。", literal: "The emperor sent Commandant of Justice Kong Guang with credentials to bestow poison on the deposed empress for self-destruction.", idiomatic: "The emperor sent Commandant of Justice Kong Guang with credentials to bestow poison on the deposed empress for suicide." },
  { zh: "丞相方進復劾奏「紅陽侯立，狡猾不閫，請下獄。", literal: "Chancellor Fangjin again impeached and memorialized: \"Marquis Li of Hongyang is crafty and does not keep to bounds—please send him to prison.", idiomatic: "Chancellor Fangjin again impeached, saying, \"Marquis Li of Hongyang is crafty and unbounded—please send him to prison." },
  { zh: "」上曰：「紅陽侯，朕之舅，不忍致法；", literal: "\" The emperor said: \"Marquis Li of Hongyang is Our maternal uncle—we cannot bear to apply the law;", idiomatic: "\" The emperor said, \"Marquis Li of Hongyang is Our maternal uncle—we cannot bear to apply the law;" },
  { zh: "遣就國。", literal: "send him to his state.", idiomatic: "send him to his fief." },
  { zh: "」於是方進復奏立黨友後將軍朱博、巨鹿太守孫閎，皆免官，與故光祿大夫陳鹹皆歸故郡。", literal: "\" Thereupon Fangjin again memorialized that Li's partisan associates Rear General Zhu Bo and Administrator of Julu Sun Hong were all removed from office, and together with former Grand Master of Splendor Chen Xian all returned to their native commanderies.", idiomatic: "\" Thereupon Fangjin again memorialized that Li's associates Rear General Zhu Bo and Administrator of Julu Sun Hong were all removed from office, and together with former Grand Master of Splendor Chen Xian returned to their native commanderies." },
  { zh: "鹹自知廢錮，以憂死。", literal: "Xian, knowing himself disgraced and barred, died from grief.", idiomatic: "Xian, knowing himself disgraced and barred from office, died from grief." },
  { zh: "方進智能有餘，兼通文法吏事，以儒雅緣飾法律，號為通明相，天子器重之；", literal: "Fangjin had intelligence to spare, was versed alike in classical learning, law, and clerkly affairs, and used refined elegance to adorn the laws—he was styled the Luminous Chancellor, and the Son of Heaven greatly valued him;", idiomatic: "Fangjin had intelligence to spare, was versed in classical learning, law, and clerkly affairs, and used refined elegance to adorn the laws—he was styled the Luminous Chancellor, and the emperor greatly valued him;" },
  { zh: "又善求人主微指，奏事無不當意。", literal: "he was also skilled at discerning the ruler's subtle intent; memorials on affairs never failed to suit his mind.", idiomatic: "he was also skilled at discerning the ruler's subtle intent; his memorials never failed to please." },
  { zh: "方淳于長用事，方進獨與長交，稱薦之；", literal: "When Chunyu Chang was in power, Fangjin alone associated with Chang and praised and recommended him;", idiomatic: "When Chunyu Chang was in power, Fangjin alone associated with Chang and praised and recommended him;" },
  { zh: "及長坐大逆誅，上以方進大臣，為之隱諱，方進內慚，上疏謝罪乞骸骨。", literal: "when Chang was convicted of great treason and executed, because Fangjin was a great minister the emperor concealed it for him; Fangjin was inwardly ashamed and submitted a memorial apologizing and begging to resign his bones.", idiomatic: "when Chang was convicted of great treason and executed, because Fangjin was a great minister the emperor concealed it for him; Fangjin was inwardly ashamed and submitted a memorial apologizing and asking to resign." },
  { zh: "上報曰：「定陵侯長已伏其辜，君雖交通，《傳》不雲乎：『朝過夕改，君子與之。", literal: "The emperor's reply said: \"Marquis Chang of Dingling has already suffered his punishment; though you had dealings, does not the Commentary say: 'To err in the morning and reform by evening—the gentleman approves it.", idiomatic: "The emperor replied, \"Marquis Chang of Dingling has already suffered his punishment; though you had dealings, does not the Commentary say, 'To err in the morning and reform by evening—the gentleman approves it." },
  { zh: "』君何疑焉！", literal: "' Why do you doubt?", idiomatic: "' Why do you doubt?" },
  { zh: "其專心壹意，毋怠醫藥，以自持。", literal: "Devote your mind single-heartedly; do not neglect medicine and healing, to sustain yourself.", idiomatic: "Devote yourself single-heartedly; do not neglect medicine and healing, to sustain yourself." },
  { zh: "」方進起視事，復條奏長所厚善京光尹孫寶、右扶風蕭育，刺史二千石以上，免二十餘人。", literal: "\" Fangjin rose and resumed duties; he again itemized and memorialized those Chang had favored and treated well—Metropolitan Magistrate Sun Bao, Right Commander of Support Feng Xiao Yu, regional inspectors and those at two thousand bushels and above—more than twenty were removed.", idiomatic: "\" Fangjin resumed duties; he again itemized and memorialized those Chang had favored—Metropolitan Magistrate Sun Bao, Right Commander of Support Xiao Yu, regional inspectors and officials at two thousand bushels and above—more than twenty were removed." },
  { zh: "函谷都尉、建平侯杜業，素與方進不平，方進奏「業受紅陽侯書聽請，不敬，」免，就國。", literal: "Commandant of Hangu Pass and Marquis of Jianping Du Ye had long been at odds with Fangjin; Fangjin memorialized: \"Ye received Hongyang Marquis Li's letter and granted requests—disrespectful,\" and he was removed and sent to his state.", idiomatic: "Commandant of Hangu Pass and Marquis of Jianping Du Ye had long been at odds with Fangjin; Fangjin memorialized that Ye had received Marquis Li of Hongyang's letter and granted requests—disrespectful—and he was removed and sent to his fief." },
  { zh: "上以王莽首發大奸，稱其忠直；", literal: "The emperor because Wang Mang had first exposed the great treachery praised his loyalty and uprightness;", idiomatic: "Because Wang Mang had first exposed the great treachery, the emperor praised his loyalty and uprightness;" },
  { zh: "王根因薦莽自代。", literal: "Wang Gen thereupon recommended Mang to replace himself.", idiomatic: "Wang Gen thereupon recommended Mang to replace himself." },
  { zh: "丙寅，以莽為大司馬，時年三十八。", literal: "On bingyin, Mang was made Grand Marshal; he was then thirty-eight years old.", idiomatic: "On bingyin, Mang was made Grand Marshal at the age of thirty-eight." },
  { zh: "莽既拔出同列，繼四父而輔政，欲令名譽過前人，遂克己不倦。", literal: "Mang, having already drawn himself above his peers and succeeding four fathers in assisting government, wished to make his reputation surpass those before him and thereupon restrained himself without weariness.", idiomatic: "Mang, having risen above his peers and succeeding four fathers in government, wished his reputation to surpass his predecessors and thereupon restrained himself tirelessly." },
  { zh: "聘諸賢良以為掾、史，賞賜、邑錢悉以享士，愈為儉約，母病，公卿列侯遣夫人問疾，莽妻迎之，衣不曳地，布蔽膝，見之者以為僮使，問知其夫人，皆驚。", literal: "He engaged worthy men as clerks and scribes; rewards, gifts, and fief monies he entirely used to entertain scholars; he became ever more frugal—when his mother was ill, grandees and marquises sent their wives to inquire after her illness; Mang's wife received them in clothes that did not trail the ground, with cloth covering her knees; those who saw her took her for a servant; on learning she was his wife, all were startled.", idiomatic: "He engaged worthy men as clerks and scribes; rewards, gifts, and fief income he entirely used to entertain scholars; he became ever more frugal—when his mother was ill, grandees and marquises sent their wives to inquire; Mang's wife received them in clothes that did not trail the ground, with cloth covering her knees; visitors took her for a servant and were startled to learn she was his wife." },
  { zh: "其飾名如此。", literal: "He adorned his reputation to this degree.", idiomatic: "He cultivated his reputation to this degree." },
  { zh: "丞相方進、大司空武奏言：「《春秋》之義，用貴治賤，不以卑臨尊。", literal: "Chancellor Fangjin and Grand Minister of Works Wu memorialized, saying: \"The meaning of the Spring and Autumn is to use the noble to govern the base and not to let the low oversee the high.", idiomatic: "Chancellor Fangjin and Grand Minister of Works Wu memorialized, saying, \"The Spring and Autumn teaches that the noble govern the base and the low must not oversee the high." },
  { zh: "刺史位下大夫而臨二千石，輕重不相準。", literal: "Regional inspectors rank below grand masters of the palace yet oversee those at two thousand bushels—the weight and lightness do not match.", idiomatic: "Regional inspectors rank below grand masters of the palace yet oversee officials at two thousand bushels—the ranks do not match." },
  { zh: "臣請罷刺史，更置州牧以應古制！", literal: "Your subject requests abolishing regional inspectors and reestablishing provincial governors to accord with ancient institutions!", idiomatic: "Your subject requests abolishing regional inspectors and reestablishing provincial governors to accord with the ancient institutions!" },
  { zh: "」十二月，罷刺史，更置州牧，秩二千石。", literal: "\" In the twelfth month, regional inspectors were abolished and provincial governors were reestablished, rank two thousand bushels.", idiomatic: "\" In the twelfth month regional inspectors were abolished and provincial governors were reestablished at the rank of two thousand bushels." },
  { zh: "犍為郡於水濱得古磬十六枚，議者以為善祥。", literal: "Qianwei Commandery obtained sixteen ancient stone chimes by the waterside; those who discussed it took them as a good omen.", idiomatic: "Qianwei Commandery found sixteen ancient stone chimes by the waterside; commentators regarded them as a favorable omen." },
  { zh: "劉向因是說上：「宜興辟雍，設庠序，陳禮樂，隆雅頌之聲，盛揖讓之容，以風化天下。", literal: "Liu Xiang thereupon addressed the emperor, saying: \"You should raise the Imperial Academy, establish schools, display ritual and music, elevate the sounds of the Elegantiae and Hymns, and magnify the bearing of bowing and yielding, to transform the realm by custom.", idiomatic: "Liu Xiang thereupon urged the emperor, saying, \"You should establish the Imperial Academy, set up schools, display ritual and music, elevate the sounds of the Odes, and magnify the bearing of courtesy and yielding, to transform the realm through custom." },
  { zh: "如此而不治者，未之有也。", literal: "To do this and yet not achieve order—never has there been such a case.", idiomatic: "To do this and yet fail to bring order—never has there been such a case." },
  { zh: "或曰：不能具禮。", literal: "Some say: one cannot fully provide the rites.", idiomatic: "Some say the rites cannot be fully provided." },
  { zh: "禮以養人為本，如有過差，是過而養人也。", literal: "Rites take nourishing people as their root; if there are excesses or shortcomings, that is erring yet still nourishing people.", idiomatic: "Rites take nourishing people as their foundation; if there are shortcomings, that is erring yet still nourishing people." },
  { zh: "刑罰之過或至死傷，今之刑非皋陶之法也，而有司請定法，削則削，筆則筆，救時務也。", literal: "Excesses in punishments may even reach death and injury; today's punishments are not Gao Yao's law, yet the responsible offices request fixing the law—cut then cut, write then write—to rescue present affairs.", idiomatic: "Excesses in punishment may even reach death and injury; today's punishments are not Gao Yao's law, yet the responsible offices request fixing the statutes—cut here, add there—to meet present needs." },
  { zh: "至於禮樂，則曰不敢，是敢於殺人、不敢於養人也。", literal: "As for ritual and music, they then say they dare not—this is daring to kill people yet not daring to nourish people.", idiomatic: "As for ritual and music, they then say they dare not—this is daring to kill people yet not daring to nourish them." },
  { zh: "為其俎豆、管弦之間小不備，因是絕而不為，是去小不備而就大不備，惑莫甚焉！", literal: "Because among the sacrificial vessels and string-and-wind instruments there are slight deficiencies, they therefore cut them off entirely and do not perform them—this is leaving small deficiencies to embrace great deficiencies; confusion could hardly be greater!", idiomatic: "Because sacrificial vessels and music are slightly incomplete, they therefore abandon them entirely—this is leaving small deficiencies to embrace great ones; confusion could hardly be greater!" },
  { zh: "夫教化之比於刑法，刑法輕，是捨所重而急所輕也。", literal: "Now, comparing civilizing instruction with penal law—if penal law is treated lightly, this is abandoning what is weighty and rushing what is light.", idiomatic: "Comparing civilizing instruction with penal law: to treat penal law lightly is to abandon what is weighty and rush what is light." },
  { zh: "教化，所恃以為治也；", literal: "Civilizing instruction is what one relies on for governing;", idiomatic: "Civilizing instruction is what one relies on for governing;" },
  { zh: "刑法，所以助治也；", literal: "penal law is what assists governing;", idiomatic: "penal law is what assists governing;" },
  { zh: "今廢所恃而獨立其所助，非所以致太平也。", literal: "now to abolish what one relies on and alone establish what assists—this is not the means to bring great peace.", idiomatic: "now to abolish what one relies on and rely solely on what assists—this is not the way to bring great peace." },
  { zh: "自京師有悖逆不順之子孫，至於陷大辟、受刑戮者不絕，由不習五常之道也。", literal: "From the capital there have been unfilial and disobedient descendants without cease, down to those who fall into capital punishment and receive execution and mutilation—because they do not practice the Way of the Five Constants.", idiomatic: "From the capital unfilial and disobedient descendants have never ceased, down to those who incur capital punishment and execution—because they do not practice the Way of the Five Constants." },
  { zh: "夫承千歲之衰周，繼暴秦之餘敝，民漸漬惡俗，貪饕險詖，不閒義理，不示以大化而獨歐以刑罰，終已不改！", literal: "Now, inheriting a thousand years of Zhou in decline, succeeding the remaining ruin of violent Qin, the people have been steeped in evil custom, greedy, rapacious, treacherous, and slanderous, unacquainted with righteousness and principle; not displaying great transformation but alone striking with punishments—they will in the end never change!", idiomatic: "Inheriting a thousand years of declining Zhou and the remaining ruin of violent Qin, the people have been steeped in evil custom, greedy, rapacious, treacherous, and slanderous, unacquainted with righteousness; shown no great transformation but struck only with punishments—they will never change in the end!" },
  { zh: "」帝以向言下公卿議，丞相、大司空奏請立辟雍，按行長安城南營表；", literal: "\" The emperor sent Liu Xiang's words down to the excellencies and ministers for discussion; the chancellor and Grand Minister of Works memorialized requesting establishment of the Imperial Academy and surveyed and laid out the site south of Chang'an city;", idiomatic: "\" The emperor referred Liu Xiang's words to the excellencies and ministers for discussion; the chancellor and Grand Minister of Works memorialized requesting establishment of the Imperial Academy and surveyed the site south of Chang'an;" },
  { zh: "未作而罷。", literal: "before construction it was abandoned.", idiomatic: "before it was built the project was abandoned." },
  { zh: "時又有言「孔子布衣，養徒三千人，今天子太學弟子少。", literal: "At the time there was also a saying: \"Confucius was a commoner in cloth and nourished three thousand disciples; today the Son of Heaven's Imperial University has few students.", idiomatic: "At the time some also said, \"Confucius was a commoner in cloth and taught three thousand disciples, yet today the Son of Heaven's Imperial University has few students." },
  { zh: "」於是增弟子員三千人，歲餘，復如故。", literal: "\" Thereupon the number of disciples was increased by three thousand; after more than a year, it returned as before.", idiomatic: "\" Thereupon the number of disciples was increased by three thousand; after more than a year it returned to what it had been." },
  { zh: "劉向自見得信於上，故常顯訟宗室，譏刺王氏及在位大臣，其言多痛切，發於至誠。", literal: "Liu Xiang himself saw that he had won the emperor's trust, and therefore often openly pleaded for the imperial clan, ridiculing and criticizing the Wang clan and the great ministers in office; his words were mostly bitter and cutting, arising from utmost sincerity.", idiomatic: "Liu Xiang saw that he had won the emperor's trust and therefore often openly pleaded for the imperial clan, ridiculing the Wang clan and the great ministers in office; his words were mostly bitter and cutting, arising from utmost sincerity." },
  { zh: "上數欲用向為九卿，輒不為王氏居位者及丞相、御史所持，故終不遷，居列大夫官前後三十餘年而卒。", literal: "The emperor several times wished to employ Xiang among the Nine Ministers, but each time those of the Wang clan in position and the chancellor and censor held him back, so he was never promoted in the end; he remained in ranked grandee offices for more than thirty years altogether and died.", idiomatic: "The emperor several times wished to appoint Xiang among the Nine Ministers, but each time Wang clan members in power and the chancellor and censor blocked it, so he was never promoted; he remained in ranked grandee offices for more than thirty years and died." },
  { zh: "後十三歲而王氏代漢。", literal: "Thirteen years later the Wang clan replaced Han.", idiomatic: "Thirteen years later the Wang clan supplanted Han." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
